import subprocess,time,select,os
def capture(m,s,timeout=20):
    p=subprocess.Popen(["./executable","-m",m,"--exit-after-modules","1","-s",str(s)],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    start=time.time(); buf=b''; events=[]
    p.stdout.flush() if False else None
    os.set_blocking(p.stdout.fileno(),False)
    while time.time()-start<timeout:
        r,_,_=select.select([p.stdout],[],[],0.05)
        if r:
            data=os.read(p.stdout.fileno(),65536)
            if data:
                events.append((round(time.time()-start,3),len(data),data[:80]))
                buf+=data
            elif p.poll() is not None:
                break
        if p.poll() is not None:
            # drain
            try:
                data=os.read(p.stdout.fileno(),65536)
                if data: events.append((round(time.time()-start,3),len(data),data[:80]))
            except: pass
            break
    if p.poll() is None: p.kill()
    print(m,s,"events",len(events),"total",len(buf))
    for e in events[:200]: print(e)
capture("bootlog",1000)
PY"}

