import subprocess,time,select,os,sys
def capture(args,timeout=12,max_events=120):
    p=subprocess.Popen(["./executable"]+args,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    start=time.time(); buf=b''; events=[]
    os.set_blocking(p.stdout.fileno(),False)
    while time.time()-start<timeout:
        r,_,_=select.select([p.stdout],[],[],0.02)
        if r:
            try: data=os.read(p.stdout.fileno(),65536)
            except: data=b''
            if data:
                events.append((round(time.time()-start,3),len(data),data[:120])); buf+=data
                if len(events)>=max_events and p.poll() is None:
                    # continue maybe stop early analysis
                    pass
            elif p.poll() is not None: break
        if p.poll() is not None:
            try:
                data=os.read(p.stdout.fileno(),65536)
                if data: events.append((round(time.time()-start,3),len(data),data[:120])); buf+=data
            except: pass
            break
    finished=p.poll() is not None
    if not finished: p.kill(); p.wait()
    print("ARGS",args,"finished",finished,"dur %.2f"%(time.time()-start),"events",len(events),"total",len(buf))
    for e in events[:80]: print(e)
    if len(events)>80: print("... last",events[-5:])
    return buf
PY
