//! A very small implementation of the `terminal_size` API surface used by
//! clap's `wrap_help` support.
//!
//! On Unix the size is obtained with the `TIOCGWINSZ` ioctl.  Like the
//! upstream crate, stdout is tried first, then stderr and finally stdin.
//! A terminal reporting zero columns is not treated as a useful size.

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

/// Return the size of the terminal attached to stdout, stderr or stdin.
#[cfg(unix)]
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        let mut winsize: libc::winsize = unsafe { std::mem::zeroed() };
        let result = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) };
        if result == 0 && winsize.ws_col > 0 {
            return Some((Width(winsize.ws_col), Height(winsize.ws_row)));
        }
    }
    None
}

/// Return the size of the terminal on non-Unix targets.
#[cfg(not(unix))]
pub fn terminal_size() -> Option<(Width, Height)> {
    None
}
RS
