{"command":"cat > src/duration.rs << 'RS'
//! Parsing for the `--exit-after-time` argument.
//!
//! This implements the compact duration syntax used by the executable:
//! a sequence of numbers followed by time units, such as `2h10min`,
//! `1.5s` or `250ms`.  The error messages intentionally match the ones
//! users of that syntax get from the original duration parser.

use std::time::Duration;

const TOO_LARGE: &str =
    "number is too large or cannot be represented without a lack of precision \
     (values below 1ns are not supported)";

#[derive(Debug, Clone, PartialEq, Eq)]
enum Error {
    Empty,
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit(String),
    NoUnit(u64),
    NumberTooLarge,
}

impl Error {
    fn message(&self) -> String {
        // Error numbers inside the source string are byte offsets, which
        // is also how the parser below tracks them.
        match self {
            Error::Empty => "value was empty".to_string(),
            Error::InvalidCharacter(offset) => format!("invalid character at {offset}"),
            Error::NumberExpected(offset) => format!("expected number at {offset}"),
            Error::UnknownUnit(unit) => format!(
                "unknown time unit {unit:?}, supported units: ns, us/µs, ms, sec, \
                 min, hours, days, weeks, months, years (and few variations)"
            ),
            Error::NoUnit(value) => {
                format!("time unit needed, for example {value}sec or {value}ms")
            }
            Error::NumberTooLarge => TOO_LARGE.to_string(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Unit {
    Nanos,
    Micros,
    Millis,
    Seconds,
    Minutes,
    Hours,
    Days,
    Weeks,
    Months,
    Years,
}

impl Unit {
    fn from_name(name: &str) -> Option<Self> {
        Some(match name {
            "ns" | "nsec" | "nanos" => Unit::Nanos,
            "us" | "µs" | "usec" => Unit::Micros,
            "ms" | "msec" | "millis" => Unit::Millis,
            "s" | "sec" | "secs" | "second" | "seconds" => Unit::Seconds,
            "m" | "min" | "mins" | "minute" | "minutes" => Unit::Minutes,
            "h" | "hr" | "hrs" | "hour" | "hours" => Unit::Hours,
            "d" | "day" | "days" => Unit::Days,
            "w" | "week" | "weeks" => Unit::Weeks,
            "M" | "month" | "months" => Unit::Months,
            "y" | "yr" | "yrs" | "year" | "years" => Unit::Years,
            _ => return None,
        })
    }

    fn seconds(self) -> u64 {
        match self {
            Unit::Seconds => 1,
            Unit::Minutes => 60,
            Unit::Hours => 3_600,
            Unit::Days => 86_400,
            Unit::Weeks => 604_800,
            Unit::Months => 2_630_016,
            Unit::Years => 31_557_600,
            Unit::Nanos | Unit::Micros | Unit::Millis => 0,
        }
    }

    fn nanos(self) -> u64 {
        match self {
            Unit::Nanos => 1,
            Unit::Micros => 1_000,
            Unit::Millis => 1_000_000,
            Unit::Seconds => 1_000_000_000,
            Unit::Minutes => 60_000_000_000,
            _ => 0,
        }
    }
}

#[derive(Default)]
struct Accumulator {
    secs: u64,
    nanos: u64,
}

impl Accumulator {
    fn add_secs(&mut self, secs: u64) -> Result<(), Error> {
        self.secs = self
            .secs
            .checked_add(secs)
            .ok_or(Error::NumberTooLarge)?;
        Ok(())
    }

    fn add_nanos(&mut self, nanos: u64) -> Result<(), Error> {
        // Deliberately use `>` in the normalisation below: exactly one
        // second worth of nanoseconds is left for `Duration::new` to
        // normalise when the total duration is finally built.
        let total = self.nanos as u128 + nanos as u128;
        if total > 1_000_000_000 {
            self.add_secs((total / 1_000_000_000) as u64)?;
            self.nanos = (total % 1_000_000_000) as u64;
        } else {
            self.nanos = total as u64;
        }
        Ok(())
    }

    fn add(&mut self, value: u64, fraction: Option<(u64, u64)>, unit: Unit) -> Result<(), Error> {
        // The integer part of a sub-second component is accumulated in
        // nanoseconds.  Everything from seconds upwards accumulates its
        // integer part in seconds.
        match unit {
            Unit::Nanos | Unit::Micros | Unit::Millis => {
                let ns = value
                    .checked_mul(unit.nanos())
                    .ok_or(Error::NumberTooLarge)?;
                self.add_nanos(ns)?;
            }
            _ => {
                let secs = value
                    .checked_mul(unit.seconds())
                    .ok_or(Error::NumberTooLarge)?;
                self.add_secs(secs)?;
            }
        }

        if let Some((fraction_value, scale)) = fraction {
            if fraction_value != 0 {
                match unit {
                    Unit::Hours | Unit::Days | Unit::Weeks | Unit::Months | Unit::Years => {
                        let numerator = fraction_value
                            .checked_mul(unit.seconds())
                            .ok_or(Error::NumberTooLarge)?;
                        if numerator % scale != 0 {
                            return Err(Error::NumberTooLarge);
                        }
                        self.add_secs(numerator / scale)?;
                    }
                    _ => {
                        let numerator = fraction_value
                            .checked_mul(unit.nanos())
                            .ok_or(Error::NumberTooLarge)?;
                        if numerator % scale != 0 {
                            return Err(Error::NumberTooLarge);
                        }
                        self.add_nanos(numerator / scale)?;
                    }
                }
            }
        }
        Ok(())
    }

    fn finish(self) -> Duration {
        Duration::new(self.secs, self.nanos as u32)
    }
}

struct Parser<'a> {
    source: &'a str,
    chars: Vec<(usize, char)>,
    index: usize,
    current: Accumulator,
}

impl<'a> Parser<'a> {
    fn new(source: &'a str) -> Self {
        Self {
            source,
            chars: source.char_indices().collect(),
            index: 0,
            current: Accumulator::default(),
        }
    }

    fn peek(&self) -> Option<(usize, char)> {
        self.chars.get(self.index).copied()
    }

    fn bump(&mut self) -> Option<(usize, char)> {
        let current = self.peek();
        if current.is_some() {
            self.index += 1;
        }
        current
    }

    fn skip_whitespace(&mut self) {
        while let Some((_, char)) = self.peek() {
            if !char.is_whitespace() {
                break;
            }
            self.index += 1;
        }
    }

    fn parse(mut self) -> Result<Duration, Error> {
        loop {
            self.skip_whitespace();
            let Some((offset, first)) = self.peek() else {
                break;
            };
            if !first.is_ascii_digit() {
                return Err(Error::NumberExpected(offset));
            }
            self.parse_component()?;
        }
        Ok(self.current.finish())
