        if let Some((offset, char)) = self.peek() {
            if !char.is_whitespace() && !char.is_ascii_digit() {
                return Err(Error::InvalidCharacter(offset));
            }
        }

        let unit = Unit::from_name(unit_name)
            .ok_or_else(|| Error::UnknownUnit(unit_name.to_string()))?;
        self.current.add(value, fraction, unit)
    }

    fn parse_fraction(&mut self, dot_offset: usize) -> Result<(u64, u64), Error> {
        let mut value: u64 = 0;
        let mut scale: u64 = 1;
        let mut digits = 0usize;
        let mut spaces_after_dot = false;

        loop {
            match self.peek() {
                Some((_, char)) if char.is_ascii_digit() => {
                    self.bump();
                    digits += 1;
                    scale = scale.checked_mul(10).ok_or(Error::NumberTooLarge)?;
                    value = value
                        .checked_mul(10)
                        .and_then(|v| v.checked_add(char as u64 - '0' as u64))
                        .ok_or(Error::NumberTooLarge)?;
                }
                Some((_, char)) if char.is_whitespace() => {
                    if digits == 0 {
                        spaces_after_dot = true;
                    }
                    self.bump();
                }
                Some((offset, char)) => {
                    if digits == 0 {
                        if spaces_after_dot {
                            return Err(Error::InvalidCharacter(offset));
                        }
                        return Err(Error::InvalidCharacter(dot_offset));
                    }
                    if is_unit_char(char) {
                        break;
                    }
                    return Err(Error::InvalidCharacter(offset));
                }
                None => {
                    if digits == 0 {
                        if spaces_after_dot {
                            return Err(Error::InvalidCharacter(self.source.len()));
                        }
                        return Err(Error::InvalidCharacter(dot_offset));
                    }
                    break;
                }
            }
        }
        Ok((value, scale))
    }
}

fn is_unit_char(char: char) -> bool {
    char.is_ascii_alphabetic() || char == 'µ'
}

/// Parse a duration such as `2h10min`.
pub fn parse_duration(source: &str) -> Result<Duration, String> {
    // A bare zero is the one value allowed without a unit.
    if source == "0" {
        return Ok(Duration::ZERO);
    }
    if source.trim().is_empty() {
        return Err(Error::Empty.message());
    }
    Parser::new(source)
        .parse()
        .map_err(|error| error.message())
}
