use std::time::{Duration, Instant};

struct Runtime {
    speed_factor: f64,
    instant_print_lines: AtomicU32,
    started: Instant,
    exit_after_time: Option<Duration>,
}

static RUNTIME: OnceLock<Runtime> = OnceLock::new();

fn runtime() -> &'static Runtime {
    RUNTIME.get_or_init(|| Runtime {
        speed_factor: 1.0,
        instant_print_lines: AtomicU32::new(0),
        started: Instant::now(),
        exit_after_time: None,
    })
}

/// Install the command line's timing parameters for this process.
pub fn init(speed_factor: f64, instant_print_lines: u32, exit_after_time: Option<Duration>) {
    let _ = RUNTIME.set(Runtime {
        speed_factor,
        instant_print_lines: AtomicU32::new(instant_print_lines),
        started: Instant::now(),
        exit_after_time,
    });
}

/// Whether the `--exit-after-time` deadline has been reached.
pub fn should_exit() -> bool {
    match runtime().exit_after_time {
        Some(limit) => runtime().started.elapsed() >= limit,
        None => false,
    }
}

/// Sleep, honouring the global speed factor and instant-line budget.
pub fn sleep(duration: Duration) {
    let runtime = runtime();
    if consume_instant_line(runtime) {
        std::thread::sleep(Duration::from_millis(1));
        return;
    }
    let scaled = duration.as_secs_f64() / runtime.speed_factor;
    let millis = if scaled.is_finite() && scaled > 0.0 {
        (scaled * 1_000.0).ceil() as u64
    } else {
        0
    };
    std::thread::sleep(Duration::from_millis(millis.max(1)));
}

/// Print `text` one character at a time, sleeping after each one.
///
/// This is used both for the slow, noisy line printer effect of a
/// computer booting and for text being typed at a simulated prompt.
pub fn print_with_delay(text: &str, delay: Duration) {
    for character in text.chars() {
        let mut encoded = [0u8; 4];
        let buffer = character.encode_utf8(&mut encoded);
        write_stdout(buffer).unwrap();
        sleep(delay);
    }
}

/// Print text without adding a line ending.
///
/// Most output should go through this function or [`print_line`].
/// It writes directly to standard output and flushes immediately,
/// which matters for progress indicators and other output rewriting
/// the current line in place: without a flush, users would only see
/// several updates at once whenever a buffer happened to fill up.
pub fn print_str(buffer: &str) {
    write_stdout(buffer).unwrap();
}

/// Print a complete line, using a CRLF line ending.
pub fn print_line(text: &str) {
    print_str(text);
    print_str("\r\n");
}

/// Erase the current terminal line and move to its start.
pub fn erase_line() {
    print_str("\x1b[2K\x1b[0G");
}

/// Move up one line, erase it, and move to its start.
pub fn move_up_and_erase_line() {
    print_str("\x1b[1A\x1b[2K\x1b[0G");
}

fn terminal_width() -> Option<u16> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        let mut winsize: libc::winsize = unsafe { std::mem::zeroed() };
        let result = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) };
        if result == 0 && winsize.ws_col > 0 {
            return Some(winsize.ws_col);
        }
    }
    None
}

/// Return the current terminal width.
pub fn get_terminal_width() -> u16 {
    if let Some(width) = terminal_width() {
        width
    } else {
        panic!("Couldn't get terminal width. Is an interactive terminal attached?")
    }
}

fn consume_instant_line(runtime: &Runtime) -> bool {
    runtime
        .instant_print_lines
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |left| {
            if left > 0 {
                Some(left - 1)
            } else {
                None
            }
        })
        .is_ok()
}

/// Move the cursor up `lines` lines.
pub fn move_up(lines: u32) {
    print_str(&format!("\x1b[{lines}A"));
}

fn write_stdout(buffer: &str) -> io::Result<()> {
    let mut stdout = io::stdout().lock();
    stdout.write_all(buffer.as_bytes())?;
    stdout.flush()
}
