//! Command line definition for genact.

use crate::duration::parse_duration;
use clap::{value_parser, Arg, ArgAction, Command};
use clap_complete::Shell;
use std::time::Duration;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Module {
    Ansible,
    Bootlog,
    Botnet,
    Bruteforce,
    Cargo,
    Cc,
    Composer,
    Cryptomining,
    DockerBuild,
    DockerImageRm,
    Download,
    Julia,
    KernelCompile,
    Memdump,
    Mkinitcpio,
    Rkhunter,
    Simcity,
    Terraform,
    Uv,
    Weblog,
    Wpt,
}

pub const ALL_MODULES: [Module; 21] = [
    Module::Ansible,
    Module::Bootlog,
    Module::Botnet,
    Module::Bruteforce,
    Module::Cargo,
    Module::Cc,
    Module::Composer,
    Module::Cryptomining,
    Module::DockerBuild,
    Module::DockerImageRm,
    Module::Download,
    Module::Julia,
    Module::KernelCompile,
    Module::Memdump,
    Module::Mkinitcpio,
    Module::Rkhunter,
    Module::Simcity,
    Module::Terraform,
    Module::Uv,
    Module::Weblog,
    Module::Wpt,
];

impl Module {
    pub fn name(self) -> &'static str {
        match self {
            Module::Ansible => "ansible",
            Module::Bootlog => "bootlog",
            Module::Botnet => "botnet",
            Module::Bruteforce => "bruteforce",
            Module::Cargo => "cargo",
            Module::Cc => "cc",
            Module::Composer => "composer",
            Module::Cryptomining => "cryptomining",
            Module::DockerBuild => "docker_build",
            Module::DockerImageRm => "docker_image_rm",
            Module::Download => "download",
            Module::Julia => "julia",
            Module::KernelCompile => "kernel_compile",
            Module::Memdump => "memdump",
            Module::Mkinitcpio => "mkinitcpio",
            Module::Rkhunter => "rkhunter",
            Module::Simcity => "simcity",
            Module::Terraform => "terraform",
            Module::Uv => "uv",
            Module::Weblog => "weblog",
            Module::Wpt => "wpt",
        }
    }

    pub fn from_name(name: &str) -> Self {
        ALL_MODULES
            .into_iter()
            .find(|module| module.name() == name)
            .expect("clap only accepts known module names")
    }
}

#[derive(Debug, Clone)]
pub struct Args {
    pub list_modules: bool,
    pub modules: Vec<Module>,
    pub speed_factor: f64,
    pub instant_print_lines: u32,
    pub inhibit: bool,
    pub exit_after_time: Option<Duration>,
    pub exit_after_modules: Option<u32>,
    pub print_completions: Option<Shell>,
    pub print_manpage: bool,
}

fn parse_speed_factor(source: &str) -> Result<f64, String> {
    let factor: f64 = source.parse().map_err(|error| error.to_string())?;
    if factor < 0.01 {
        Err("Speed factor must be larger than 0.01".to_string())
    } else {
        Ok(factor)
    }
}

fn parse_exit_after_modules(source: &str) -> Result<u32, String> {
