//! Termination signals end the show politely: a final line is
//! written and the process exits successfully, as if whatever fake
//! work was in progress had been saved.

const MESSAGE: &[u8] = b"Saving work to disk...\n";

extern "C" fn handle_signal(_signal: libc::c_int) {
    unsafe {
        libc::write(
            libc::STDOUT_FILENO,
            MESSAGE.as_ptr() as *const libc::c_void,
            MESSAGE.len(),
        );
        libc::_exit(0);
    }
}

pub fn install() {
    unsafe {
        let handler = handle_signal as *const () as libc::sighandler_t;
        libc::signal(libc::SIGINT, handler);
        libc::signal(libc::SIGTERM, handler);
        libc::signal(libc::SIGHUP, handler);
    }
}
