fn parse_speed_factor(source: &str) -> Result<f64, String> {
    let factor: f64 = source.parse().map_err(|error| error.to_string())?;
    if factor < 0.01 {
        Err("Speed factor must be larger than 0.01".to_string())
    } else {
        Ok(factor)
    }
}

fn parse_exit_after_modules(source: &str) -> Result<u32, String> {
    let count: u32 = source.parse().map_err(|error| error.to_string())?;
    if count == 0 {
        Err("Must be larger than 0".to_string())
    } else {
        Ok(count)
    }
}

pub fn build_command() -> Command {
    Command::new("genact")
        .version("1.5.1")
        .about("A nonsense activity generator")
        .author("Sven-Hendrik Haase <svenstaro@gmail.com>")
        .arg(
            Arg::new("list-modules")
                .short('l')
                .long("list-modules")
                .help("List available modules")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("modules")
                .short('m')
                .long("modules")
                .help("Run only these modules")
                .value_name("MODULES")
                .value_parser([
                    "ansible",
                    "bootlog",
                    "botnet",
                    "bruteforce",
                    "cargo",
                    "cc",
                    "composer",
                    "cryptomining",
                    "docker_build",
                    "docker_image_rm",
                    "download",
                    "julia",
                    "kernel_compile",
                    "memdump",
                    "mkinitcpio",
                    "rkhunter",
                    "simcity",
                    "terraform",
                    "uv",
                    "weblog",
                    "wpt",
                ])
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("speed-factor")
                .short('s')
                .long("speed-factor")
                .help("Global speed factor")
                .value_name("SPEED_FACTOR")
                .default_value("1")
                .value_parser(parse_speed_factor),
        )
        .arg(
            Arg::new("instant-print-lines")
                .short('i')
                .long("instant-print-lines")
                .help("Instantly print this many lines")
                .value_name("INSTANT_PRINT_LINES")
                .default_value("0")
                .value_parser(value_parser!(u32)),
        )
        .arg(
            Arg::new("inhibit")
                .long("inhibit")
                .help("Keep the computer awake and the display on while genact is running")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("exit-after-time")
                .long("exit-after-time")
                .help("Exit after running for this long (format example: 2h10min)")
                .value_name("EXIT_AFTER_TIME")
                .value_parser(parse_duration),
        )
        .arg(
            Arg::new("exit-after-modules")
                .long("exit-after-modules")
                .help("Exit after running this many modules")
                .value_name("EXIT_AFTER_MODULES")
                .value_parser(parse_exit_after_modules),
        )
        .arg(
            Arg::new("print-completions")
                .long("print-completions")
                .help("Generate completion file for a shell")
                .value_name("shell")
                .value_parser(value_parser!(Shell)),
        )
        .arg(
            Arg::new("print-manpage")
                .long("print-manpage")
                .help("Generate man page")
                .action(ArgAction::SetTrue),
        )
}

impl Args {
    pub fn from_matches(matches: &clap::ArgMatches) -> Self {
        Self {
            list_modules: matches.get_flag("list-modules"),
            modules: matches
                .get_many::<String>("modules")
                .map(|values| values.map(|name| Module::from_name(name)).collect())
                .unwrap_or_default(),
            speed_factor: *matches
                .get_one::<f64>("speed-factor")
                .expect("speed factor has a default"),
            instant_print_lines: *matches
                .get_one::<u32>("instant-print-lines")
                .expect("instant print lines has a default"),
            inhibit: matches.get_flag("inhibit"),
            exit_after_time: matches.get_one::<Duration>("exit-after-time").copied(),
            exit_after_modules: matches.get_one::<u32>("exit-after-modules").copied(),
            print_completions: matches.get_one::<Shell>("print-completions").copied(),
            print_manpage: matches.get_flag("print-manpage"),
        }
    }
}
