//! Small random-generation and formatting helpers used by modules.

use rand::seq::SliceRandom;
use rand::{Rng, RngCore};

pub fn rng() -> impl RngCore {
    rand::thread_rng()
}

pub fn range(min: u64, max_exclusive: u64) -> u64 {
    rand::thread_rng().gen_range(min..max_exclusive)
}

pub fn range_inclusive(min: u64, max: u64) -> u64 {
    rand::thread_rng().gen_range(min..=max)
}

pub fn range_usize(min: usize, max_exclusive: usize) -> usize {
    rand::thread_rng().gen_range(min..max_exclusive)
}

pub fn probability(chance: f64) -> bool {
    rand::thread_rng().gen_bool(chance.clamp(0.0, 1.0))
}

pub fn choose<'a, T>(items: &'a [T]) -> &'a T {
    items
        .choose(&mut rand::thread_rng())
        .expect("choose from a non-empty list")
}

pub fn choose_string(items: &[&str]) -> String {
    choose(items).to_string()
}

/// Pick `count` distinct items, or fewer if the list is too short.
pub fn choose_multiple<'a, T>(items: &'a [T], count: usize) -> Vec<&'a T> {
    let mut indices: Vec<usize> = (0..items.len()).collect();
    indices.shuffle(&mut rand::thread_rng());
    indices
        .into_iter()
        .take(count.min(items.len()))
        .map(|index| &items[index])
        .collect()
}

/// A plausible three-part software version.
pub fn version() -> String {
    let major = choose(&[0, 0, 0, 1, 1, 1, 2, 2, 3, 4]);
    format!(
        "{major}.{}.{}",
        range(0, 80),
        range(0, 60)
    )
}

/// A version with the somewhat larger component ranges the simulated
/// PHP package manager tends to print.
pub fn wide_version() -> String {
    format!("{}.{}.{}", range(0, 40), range(0, 60), range(0, 50))
}

pub fn hex_string(bytes: usize) -> String {
    let mut rng = rand::thread_rng();
    let mut output = String::with_capacity(bytes * 2);
    for _ in 0..bytes {
        output.push_str(&format!("{:02x}", rng.gen::<u8>()));
    }
    output
}

pub fn short_hash() -> String {
    hex_string(6)
}

pub fn ipv4() -> String {
    format!(
        "{}.{}.{}.{}",
        range(0, 256),
        range(0, 256),
        range(0, 256),
        range(0, 256)
    )
}

pub fn ipv6() -> String {
    let mut rng = rand::thread_rng();
    (0..8)
        .map(|_| format!("{:x}", rng.gen::<u16>()))
        .collect::<Vec<_>>()
        .join(":")
}

pub fn ip() -> String {
    if probability(0.5) {
        ipv4()
    } else {
        ipv6()
    }
}

pub fn mac() -> String {
    let mut rng = rand::thread_rng();
    (0..6)
        .map(|_| format!("{:02x}", rng.gen::<u8>()))
        .collect::<Vec<_>>()
        .join(":")
}

/// Format a byte count using binary units and two decimal places.
pub fn human_binary(bytes: u64, space_before_unit: bool) -> String {
    let space = if space_before_unit { " " } else { "" };
    if bytes >= 1 << 30 {
        format!("{:.2}{space}GiB", bytes as f64 / (1u64 << 30) as f64)
    } else if bytes >= 1 << 20 {
        format!("{:.2}{space}MiB", bytes as f64 / (1u64 << 20) as f64)
    } else if bytes >= 1 << 10 {
        format!("{:.2}{space}KiB", bytes as f64 / (1u64 << 10) as f64)
    } else {
        format!("{bytes}{space}B")
    }
}

/// The `=`-and-block progress bar used by the Julia and download
/// simulations.  At exactly 100% the moving block sits in the last
