//! Small random-generation and formatting helpers used by modules.

use rand::seq::SliceRandom;
use rand::{Rng, RngCore};

pub fn rng() -> impl RngCore {
    rand::thread_rng()
}

pub fn range(min: u64, max_exclusive: u64) -> u64 {
    rand::thread_rng().gen_range(min..max_exclusive)
}

pub fn range_inclusive(min: u64, max: u64) -> u64 {
    rand::thread_rng().gen_range(min..=max)
}

pub fn range_usize(min: usize, max_exclusive: usize) -> usize {
    rand::thread_rng().gen_range(min..max_exclusive)
}

pub fn probability(chance: f64) -> bool {
    rand::thread_rng().gen_bool(chance.clamp(0.0, 1.0))
}

pub fn choose<'a, T>(items: &'a [T]) -> &'a T {
    items
        .choose(&mut rand::thread_rng())
        .expect("choose from a non-empty list")
}

pub fn choose_string(items: &[&str]) -> String {
    choose(items).to_string()
}

/// Pick `count` distinct items, or fewer if the list is too short.
pub fn choose_multiple<'a, T>(items: &'a [T], count: usize) -> Vec<&'a T> {
    let mut indices: Vec<usize> = (0..items.len()).collect();
    indices.shuffle(&mut rand::thread_rng());
    indices
        .into_iter()
        .take(count.min(items.len()))
        .map(|index| &items[index])
        .collect()
}

/// A plausible three-part software version.
pub fn version() -> String {
    let major = choose(&[0, 0, 0, 1, 1, 1, 2, 2, 3, 4]);
    format!(
        "{major}.{}.{}",
        range(0, 80),
        range(0, 60)
    )
}

