/// PHP package manager tends to print.
pub fn wide_version() -> String {
    format!("{}.{}.{}", range(0, 40), range(0, 60), range(0, 50))
}

pub fn hex_string(bytes: usize) -> String {
    let mut rng = rand::thread_rng();
    let mut output = String::with_capacity(bytes * 2);
    for _ in 0..bytes {
        output.push_str(&format!("{:02x}", rng.gen::<u8>()));
    }
    output
}

pub fn short_hash() -> String {
    hex_string(6)
}

pub fn ipv4() -> String {
    format!(
        "{}.{}.{}.{}",
        range(0, 256),
        range(0, 256),
        range(0, 256),
        range(0, 256)
    )
}

pub fn ipv6() -> String {
    let mut rng = rand::thread_rng();
    (0..8)
        .map(|_| format!("{:x}", rng.gen::<u16>()))
        .collect::<Vec<_>>()
        .join(":")
}

