/// once a file has finished.
pub fn equals_block_bar(fraction: f64, width: usize) -> String {
    if width == 0 {
        return String::new();
    }
    if fraction <= 0.0 {
        return " ".repeat(width);
    }
    if fraction > 1.0 {
        return "=".repeat(width);
    }
    let filled = ((fraction * width as f64) as usize).min(width - 1);
    let mut bar = "=".repeat(filled);
    bar.push('█');
    bar.push_str(&" ".repeat(width - filled - 1));
    bar
}

/// The Unicode spinner frames used by the `uv` simulation.
pub const BRAILLE_SPINNER: [char; 10] = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
