{"command":"cat > src/main.rs << 'RS'
mod args;
mod data;
mod duration;
mod inhibit;
mod io;
mod modules;
mod signals;
mod utils;

use args::{Args, ALL_MODULES};
use clap_complete::generate;
use rand::seq::SliceRandom;
use std::io as std_io;

fn main() -> anyhow::Result<()> {
    let mut command = args::build_command();
    let matches = command.clone().get_matches();
    let args = Args::from_matches(&matches);

    if let Some(shell) = args.print_completions {
        generate(shell, &mut command, "genact", &mut std_io::stdout());
        return Ok(());
    }
    if args.print_manpage {
        clap_mangen::Man::new(command).render(&mut std_io::stdout())?;
        return Ok(());
    }
    if args.list_modules {
        let names: Vec<&str> = ALL_MODULES.iter().map(|module| module.name()).collect();
        println!("Available modules:\n  {}", names.join("\n  "));
        return Ok(());
    }

    io::init(
        args.speed_factor,
        args.instant_print_lines,
        args.exit_after_time,
    );
    signals::install();

    let _inhibit_guard = if args.inhibit {
        Some(inhibit::try_inhibit())
    } else {
        None
    };

    let selected = if args.modules.is_empty() {
        ALL_MODULES.to_vec()
    } else {
        args.modules.clone()
    };

    let mut modules_run: u32 = 0;
    loop {
        let module = *selected
            .choose(&mut rand::thread_rng())
            .expect("at least one module is selected");
        modules::run(module);
        modules_run += 1;

        if let Some(limit) = args.exit_after_modules {
            if modules_run >= limit {
                break;
            }
        }
        if io::should_exit() {
            break;
        }
    }

    println!("Saving work to disk...");
    Ok(())
}
