use crate::io;
use crate::utils;
use rand::Rng;
use std::time::Duration;

pub fn run() {
    let mut rng = rand::thread_rng();
    // The address increases monotonically from a random aligned base,
    // just like dumping consecutive blocks of memory.
    let mut address = (rng.gen::<u64>() >> 4) << 4;
    let lines = utils::range(50, 250);

    for line_index in 0..lines {
        if io::should_exit() {
            return;
        }
        let bytes: Vec<u8> = (0..16).map(|_| rng.gen()).collect();
        if line_index > 0 {
            io::print_str("\r\n");
        }
        io::print_str(&format!("{address:016x}  {:02x} ", bytes[0]));
        for (index, byte) in bytes.iter().enumerate().skip(1) {
            io::sleep(Duration::from_millis(2));
            if index == 8 {
                io::print_str(&format!(" {byte:02x} "));
            } else {
                io::print_str(&format!("{byte:02x} "));
            }
        }
        let text: String = bytes
            .iter()
            .map(|byte| {
                if byte.is_ascii_graphic() {
                    *byte as char
                } else {
                    '.'
                }
            })
            .collect();
        io::print_str(&format!(" |{text}|"));
        address = address.wrapping_add(16);
        io::sleep(Duration::from_millis(utils::range(50, 250)));
    }
    io::print_str("\r\n");
}
