use crate::data::KERNEL_OBJECTS;
use crate::io;
use crate::utils;
use std::time::Duration;

static VERSIONS: &[&str] = &[
    "2.6.22.5-31-default",
    "2.6.32-431.el6.i686",
    "2.6.38.8-g2593b11",
    "3.17.3-1-MANJARO",
    "5.0.7-arch1-1-ARCH",
    "9.0.2.2",
    "1.5.19(0.150/4/2)",
];

static COMPRESSIONS: &[&str] = &["gzip", "bzip2", "lzma", "xz", "lz4", "zstd", "lzop"];

fn green_arrow(text: String) {
    io::print_line(&format!("\x1b[1;32m==> \x1b[0m\x1b[1m{text}\x1b[0m"));
}

fn blue_arrow(text: String) {
    io::print_line(&format!("\x1b[1;34m  -> \x1b[0m\x1b[1m{text}\x1b[0m"));
}

fn hooks() -> Vec<&'static str> {
    let mut hooks = vec!["base", "udev"];
    if utils::probability(0.5) {
        hooks.push("usr");
    }
    if utils::probability(0.5) {
        hooks.push("resume");
    }
    hooks.extend(["autodetect", "modconf", "block"]);
    if utils::probability(0.5) {
        hooks.push("net");
    }
    if utils::probability(0.4) {
        hooks.push(utils::choose(&["mdadm", "mdadm_udev"]));
    }
    for hook in ["encrypt", "keyboard", "keymap", "consolefont", "lvm2"] {
        if utils::probability(0.45) {
            hooks.push(hook);
        }
    }
    hooks.extend(["fsck", "filesystems"]);
    hooks
}

pub fn run() {
    let version = utils::choose(VERSIONS);
    let compression = utils::choose(COMPRESSIONS);
    let hooks = hooks();
    let warnings = utils::range(1, 5);

    for (preset, image) in [
        ("default", "/boot/initramfs-linux.img"),
        ("fallback", "/boot/initramfs-linux-fallback.img"),
    ] {
        green_arrow(format!(
            "Building image from preset: /etc/mkinitcpio.d/linux.preset: '{preset}'"
        ));
        blue_arrow(format!(
            "-k /boot/vmlinuz-linux -c /etc/mkinitcpio.conf -g {image}"
        ));
        green_arrow(format!("Starting build: {version}"));

        for hook in &hooks {
            if io::should_exit() {
                return;
            }
            blue_arrow(format!("Running build hook: [{hook}]"));
            io::sleep(Duration::from_millis(utils::range(200, 700)));

            // Missing-firmware warnings appear in the fallback image
            // after the modules needed to mount the root filesystem
            // have been dealt with.
            if preset == "fallback" && *hook == "block" {
                for _ in 0..warnings {
                    if io::should_exit() {
                        return;
                    }
                    let object = utils::choose(KERNEL_OBJECTS);
                    let module = object
                        .rsplit('/')
                        .next()
                        .unwrap_or(object)
                        .strip_suffix(".o")
                        .unwrap_or(object);
                    io::print_line(&format!(
                        "\x1b[1;33m==> WARNING: \x1b[0m\x1b[1mPossibly missing firmware for module: {module}\x1b[0m"
                    ));
                    io::sleep(Duration::from_millis(utils::range(0, 100)));
                }
            }
        }
        if io::should_exit() {
            return;
        }
        green_arrow("Generating module dependencies".to_string());
        green_arrow(format!(
            "Creating {compression}-compressed initcpio image: {image}"
        ));
        green_arrow("Image generation successful".to_string());
    }
}
RS"}

