use crate::data::{CRATES, KERNEL_OBJECTS};
use crate::io;
use crate::utils;
use std::time::Duration;

static FLAGS: &[&str] = &[
    "-Wextra",
    "-Wold-style-definition",
    "-Wno-unused-variable",
    "-Wno-sign-compare",
    "-Wno-unknown-pragmas",
    "-Wundef",
    "-Wno-parentheses",
    "-Wwrite-strings",
    "-fgnu89-inline",
    "-funroll-loops",
    "-fsigned-char",
    "-fPIC",
    "-pipe",
    "-mtune=generic",
    "-march=x86-64",
];

static DEFINES: &[&str] = &[
    "-DNDEBUG",
    "-DDEBUG",
    "-DMODULE_NAME=lib",
    "-DNAMESPACE=lib",
    "-D_REENTRANT",
    "-D_LIBS_REENTRANT",
    "-D_GNU_SOURCE",
    "-D_LARGEFILE64_SOURCE",
];

fn random_include() -> String {
    loop {
        let object = utils::choose(KERNEL_OBJECTS);
        if let Some((directory, _)) = object.rsplit_once('/') {
            return format!("-I{directory}");
        }
    }
}

pub fn run() {
    let compiler = utils::choose(&["gcc", "clang"]);
    let optimisation = utils::choose(&["-O0", "-O1", "-O2", "-O3", "-Os", "-Og"]);

    let mut command = format!("{compiler} -c {optimisation} -Wall");
    for _ in 0..utils::range(3, 9) {
        command.push(' ');
        command.push_str(utils::choose(FLAGS));
    }
    for _ in 0..utils::range(15, 26) {
        command.push(' ');
        command.push_str(&random_include());
    }
    for _ in 0..utils::range(0, 6) {
        command.push(' ');
        command.push_str(utils::choose(DEFINES));
    }

    let count = utils::range(100, 600) as usize;
    let mut objects: Vec<&str> = utils::choose_multiple(KERNEL_OBJECTS, count)
        .into_iter()
        .copied()
        .collect();
    objects.sort_unstable();

    for object in &objects {
        if io::should_exit() {
            return;
        }
        io::print_line(&format!("{command} -o {object}"));
        io::sleep(Duration::from_millis(utils::range(0, 300)));
    }

    let binary = utils::choose(CRATES);
    let mut link = format!("{compiler} -o {binary} ");
    for object in &objects {
        link.push_str(object);
        link.push(' ');
    }
    for _ in 0..utils::range(0, 10) {
        link.push_str(&format!("-l{} ", utils::choose(CRATES)));
    }
    io::print_line(&link);
}
