use crate::data::BOOTLOG_LINES;
use crate::io;
use crate::utils;
use std::time::Duration;

fn styled(line: &str) -> String {
    // The occasional line is shouted as an error, or has its first
    // word emphasised, in the manner of a highlighted boot log.
    if utils::probability(0.02) {
        return format!("\x1b[31mERROR: {line}\x1b[0m");
    }
    if utils::probability(0.1) {
        if let Some((first, rest)) = line.trim_start().split_once(' ') {
            let leading = &line[..line.len() - line.trim_start().len()];
            return format!("{leading}\x1b[1m{first}\x1b[0m {rest}");
        }
    }
    line.to_string()
}

pub fn run() {
    let lines = utils::range(50, 250);
    for _ in 0..lines {
        if io::should_exit() {
            return;
        }
        let line = styled(utils::choose(BOOTLOG_LINES));
        io::print_with_delay(&line, Duration::from_millis(5));
        io::print_str("\r\n");
        io::sleep(Duration::from_millis(utils::range(0, 1000)));
    }
}
