use crate::io;
use crate::utils;
use std::time::Duration;

pub fn run() {
    let clusters: Vec<u64> = (0..10).map(|_| utils::range(100, 200)).collect();
    let total: u64 = clusters.iter().sum();

    for connected in 0..=total {
        io::print_str(&format!("\rEstablishing connections: {connected:4}/{total}"));
        io::sleep(Duration::from_millis(1));
    }
    io::print_str("\r\n");

    for (index, nodes) in clusters.iter().enumerate() {
        if io::should_exit() {
            return;
        }
        io::print_line(&format!("  Cluster #{index:02} ({nodes} nodes)"));
        io::sleep(Duration::from_millis(utils::range(0, 200)));
    }

    // Every cluster takes a little while to boot.  Redraw the whole
    // list until the last of them reports that it is online.
    let mut remaining: Vec<u64> = (0..10).map(|_| utils::range(1, 30)).collect();
    loop {
        if io::should_exit() {
            return;
        }
        io::move_up(10);
        let mut all_online = true;
        for (index, nodes) in clusters.iter().enumerate() {
            if remaining[index] > 0 {
                remaining[index] -= 1;
            }
            let online = remaining[index] == 0;
            all_online &= online;
            let status = if online {
                "\x1b[1;32monline\x1b[0m"
            } else {
                "\x1b[1;33mbooting\x1b[0m"
            };
            io::erase_line();
            io::print_line(&format!("  Cluster #{index:02} ({nodes} nodes) [{status}]"));
            io::sleep(Duration::from_millis(10));
        }
        if all_online {
            break;
        }
    }

    for text in [
        "+ Synchronizing clocks... [done]",
        "+ Sending login information... [done]",
        "+ Sending command... [done]",
    ] {
        if io::should_exit() {
            return;
        }
        io::print_line(text);
        io::sleep(Duration::from_millis(utils::range(100, 600)));
    }
    io::print_line(">> Botnet update complete.");
}
