use std::time::{Duration, Instant};

fn info_line(kind: &str, source: &str, message: String) {
    let time = chrono::Local::now().format("%H:%M:%S");
    let marker = if kind == "m" {
        "\x1b[32m  m\x1b[0m"
    } else {
        "\x1b[1;36m  ℹ\x1b[0m"
    };
    io::print_line(&format!(
        "{marker}  \x1b[35m{time}\x1b[0m\x1b[30m|\x1b[0m\x1b[34m{source:<13}\x1b[0m{message}"
    ));
}

pub fn run() {
    let started = Instant::now();
    let gpus = utils::range(1, 6);
    let base_speeds: Vec<f64> = (0..gpus)
        .map(|_| 20.0 + utils::range(0, 3000) as f64 / 100.0)
        .collect();
    let mut accepted = 0u64;
    let mut since_job = 0u32;
    let lines = utils::range(200, 900);

    for _ in 0..lines {
        if io::should_exit() {
            return;
        }

        since_job += 1;
        if since_job > 20 && utils::probability(0.1) {
            since_job = 0;
            info_line(
                "info",
                "stratum",
                format!(
                    "Received new job #{}  seed: #{}  target: #{}",
                    utils::hex_string(4),
                    utils::hex_string(16),
                    utils::hex_string(12)
                ),
            );
            io::sleep(Duration::from_millis(50));
        }
        if utils::probability(0.005) {
            let gpu = utils::range(0, gpus);
            info_line(
                "info",
                &format!("CUDA{gpu}"),
                "Solution found; Submitted to stratum.buttcoin.org".to_string(),
            );
            info_line(
                "info",
                &format!("CUDA{gpu}"),
                format!("Nonce: 0x{}", utils::hex_string(8)),
            );
            info_line("info", "stratum", "Accepted.".to_string());
            accepted += 1;
        }

        let speeds: Vec<f64> = base_speeds
            .iter()
            .map(|base| base + (utils::range(0, 100) as f64 - 50.0) / 100.0)
            .collect();
        let total: f64 = speeds.iter().sum();
        let mut message = format!("Speed \x1b[1;36m{total:6.2}\x1b[0m Mh/s    ");
        for (gpu, speed) in speeds.iter().enumerate() {
            message.push_str(&format!("gpu/{gpu} \x1b[36m{speed:.2}\x1b[0m "));
        }
        let elapsed = started.elapsed().as_secs();
        message.push_str(&format!(
            "  [A{accepted}+0:R0+0:F0] Time: {:02}:{:02}",
            elapsed / 60,
            elapsed % 60
        ));
        info_line("m", "cryptominer", message);
        io::sleep(Duration::from_millis(utils::range(50, 300)));
    }
}
