use crate::io;
use crate::utils;
use rand::Rng;
use std::time::Duration;

static RAINBOW: &[u16] = &[
    203, 209, 208, 178, 178, 184, 148, 154, 119, 119, 83, 84, 48, 43, 44, 44, 38, 33, 69, 63,
    99, 99, 129, 128, 164, 163, 163, 198, 204, 203,
];

static FIRST_NAMES: &[&str] = &[
    "amelia", "ava", "benjamin", "brooklyn", "cali", "charlotte", "ciara", "clara", "daniel",
    "elijah", "ella", "emma", "ethan", "evelyn", "grace", "harmon", "harper", "henry", "irma",
    "isabella", "james", "juliana", "kieran", "liam", "lily", "logan", "lucas", "luna", "mason",
    "melany", "mia", "michael", "noah", "oliver", "olivia", "ryleigh", "sophia", "theodore",
    "violet", "william", "zoe",
];

fn random_hex(rng: &mut impl Rng, chars: usize) -> String {
    (0..chars)
        .map(|_| format!("{:x}", rng.gen_range(0..16)))
        .collect()
}

pub fn run() {
    let mut rng = rand::thread_rng();
    let hashes: Vec<String> = (0..9).map(|_| random_hex(&mut rng, 64)).collect();

    io::print_line("=> Hashes to decrypt");
    for hash in &hashes {
        io::print_line(&format!("  {hash}"));
        io::sleep(Duration::from_millis(utils::range(0, 200)));
    }
    io::print_line("");

    // A "rainbow table" is extracted one colourful cell at a time.
    let spinners = ['|', '/', '-', '\\'];
    for position in 0..RAINBOW.len() {
        if io::should_exit() {
            return;
        }
        let mut bar = String::new();
        for (cell, colour) in RAINBOW.iter().enumerate() {
            let character = if cell < position {
                '='
            } else if cell == position {
                spinners[position % spinners.len()]
            } else {
                ' '
            };
            bar.push_str(&format!("\x1b[38;5;{colour}m{character}\x1b[0m"));
        }
        io::print_str(&format!("\r=> Extracting Rainbow Table [{bar}]"));
        io::sleep(Duration::from_millis(utils::range(50, 250)));
    }
    io::print_line("");

    io::print_line("=> Begin matching");
    let mut matched = vec![0usize; hashes.len()];
    let mut first_block = true;
    while matched.iter().any(|chars| *chars < 64) {
        if !first_block {
            io::move_up(9);
        }
        first_block = false;
        for (index, hash) in hashes.iter().enumerate() {
            if io::should_exit() {
                return;
            }
            // The next hex digit of the candidate either extends the
            // known prefix or leaves it where it was.
            if matched[index] < 64 {
                let wanted = hash.as_bytes()[matched[index]] as char;
                let guessed = format!("{:x}", rng.gen_range(0..16));
                if guessed.as_bytes()[0] as char == wanted {
                    matched[index] += 1;
                }
            }
            let done = &hash[..matched[index]];
            let rest = random_hex(&mut rng, 64 - matched[index]);
            io::print_line(&format!(
                "\r :: \x1b[32m{done}\x1b[0m\x1b[31m{rest}\x1b[0m ::"
            ));
            io::sleep(Duration::from_millis(5));
        }
    }

    io::print_line("=> Match found");
    for hash in &hashes {
        let password = format!("{}{:02}", utils::choose(FIRST_NAMES), utils::range(0, 100));
        io::print_line(&format!("  {hash}:\x1b[1m{password}\x1b[0m"));
        io::sleep(Duration::from_millis(utils::range(0, 200)));
    }
}
