use crate::data::KERNEL_OBJECTS;
use crate::io;
use crate::utils;
use std::time::Duration;

static EXTENSIONS: &[&str] = &[
    "rar", "zip", "tar.gz", "tar.xz", "tar.bz2", "tar.zstd", "iso", "jpg", "png", "gif", "svg",
    "mp3", "mp4", "webm", "mkv", "flac", "ogg", "opus", "exe", "deb", "rpm", "md", "html", "php",
];

fn file_stem() -> String {
    let object = utils::choose(KERNEL_OBJECTS);
    let base = object.rsplit('/').next().unwrap_or(object);
    base.strip_suffix(".o").unwrap_or(base).to_string()
}

fn truncate(text: &str, width: usize) -> String {
    text.chars().take(width).collect()
}

fn print_progress(
    filename: &str,
    percent: u64,
    fraction: f64,
    chunk: u64,
    eta: u64,
    name_field: usize,
    bar_width: usize,
    finished: bool,
) {
    let name = truncate(filename, name_field.saturating_sub(2));
    let bar = if finished {
        "=".repeat(bar_width)
    } else {
        utils::equals_block_bar(fraction, bar_width)
    };
    let chunk_text = utils::human_binary(chunk, false);
    let speed_text = format!("{:.2}MiB/s", chunk as f64 / 1_048_576.0 * 20.0);
    io::erase_line();
    io::print_str(&format!(
        "{name:<name_field$}{percent:3}%[{bar}] {chunk_text:<11}{speed_text:<13}eta {eta}s"
    ));
}

pub fn run() {
    let width = io::get_terminal_width() as usize;
    let extension = utils::choose(EXTENSIONS);
    let files = utils::range(3, 9);
    let minimum_chunk = utils::range(300_000, 4_000_000);

    for _ in 0..files {
        if width < 55 {
            io::print_line("Terminal too small to display download progress");
            io::sleep(Duration::from_millis(50));
            if io::should_exit() {
                return;
            }
            continue;
        }

        let filename = format!("{}.{}", file_stem(), extension);
        let total = utils::range(50, 350) * 1_048_576;
        let name_field = (width - 26) / 3;
        let bar_width = width - 46 - name_field;
        let mut downloaded: u64 = 0;
        let mut first = true;

        loop {
            if io::should_exit() {
                return;
            }
            let chunk = minimum_chunk + utils::range(0, 500_000);
            let fraction = downloaded as f64 / total as f64;
            let percent = (fraction * 100.0) as u64;
            let eta = if first {
                0
            } else {
                ((total.saturating_sub(downloaded)) as f64 / (chunk as f64 * 20.0)) as u64
            };
            print_progress(
                &filename,
                percent.min(100),
                fraction,
                chunk,
                eta,
                name_field,
                bar_width,
                false,
            );
            first = false;
            io::sleep(Duration::from_millis(50));
            downloaded += chunk;
            if downloaded >= total {
                break;
            }
        }

        if io::should_exit() {
            return;
        }
        let chunk = minimum_chunk + utils::range(0, 500_000);
        print_progress(&filename, 100, 1.0, chunk, 0, name_field, bar_width, true);
        io::print_str("\r\n");
        io::sleep(Duration::from_millis(50));
    }
}
