use crate::data::{ANSIBLE_ROLES, ANSIBLE_TASKS};
use crate::io;
use crate::utils;
use std::time::Duration;

static FIRST_NAMES: &[&str] = &[
    "abigayle", "anthony", "bradford", "buddy", "erin", "ernestine", "estel", "francisco", "fred",
    "luciano", "lyda", "rosalia", "sally", "thalia", "tianna", "wilford", "zoe",
];

static WORDS: &[&str] = &[
    "ad", "aperiam", "architecto", "at", "dolores", "eligendi", "excepturi", "libero", "non",
    "praesentium", "quaerat", "sequi", "sint", "temporibus", "voluptas",
];

fn padded_header(text: String, width: usize) -> String {
    let plain = format!("{text} ");
    let stars = width.saturating_sub(plain.chars().count());
    format!("{plain}{}", "*".repeat(stars))
}

fn task_status() -> (&'static str, u32) {
    let roll = utils::range(0, 100);
    if roll < 82 {
        ("ok", 32)
    } else if roll < 92 {
        ("changed", 33)
    } else if roll < 97 {
        ("skipping", 36)
    } else {
        ("failed", 31)
    }
}

pub fn run() {
    let width = io::get_terminal_width() as usize;
    let play = format!(
        "setup {}_{}",
        utils::choose(FIRST_NAMES),
        utils::choose(WORDS)
    );
    io::print_line(&padded_header(format!("PLAY [{play}]"), width));

    let hosts: Vec<String> = (0..utils::range(5, 26)).map(|_| utils::ip()).collect();
    let role_count = utils::range(2, 6);
    let mut first_task = true;

    // The first task is always Ansible's own fact gathering.
    let mut task_groups: Vec<(String, Vec<String>)> = vec![(
        "Gathering Facts".to_string(),
        vec!["Gathering Facts".to_string()],
    )];
    for role in utils::choose_multiple(ANSIBLE_ROLES, role_count as usize) {
        let tasks = (0..utils::range(2, 9))
            .map(|_| format!("{role} : {}", utils::choose(ANSIBLE_TASKS)))
            .collect();
        task_groups.push((role.to_string(), tasks));
    }

    for (_, tasks) in task_groups {
        for task in tasks {
            io::print_line("");
            io::print_str(&padded_header(format!("TASK [{task}]"), width));

            // A task often has a dominant outcome, with a few hosts
            // wandering away from it.
            let dominant = if first_task {
                ("ok", 32)
            } else if utils::probability(0.06) {
                *utils::choose(&[("changed", 33), ("skipping", 36), ("failed", 31)])
            } else {
                ("ok", 32)
            };
            first_task = false;

            for (index, host) in hosts.iter().enumerate() {
                let (status, colour) = if utils::probability(0.85) {
                    dominant
                } else {
                    task_status()
                };
                let line = format!("\x1b[{colour}m{status}: [{host}]\x1b[0m");
                if index == 0 {
                    // The header has no line ending of its own; on a
                    // real terminal its padding pushes this first
                    // result onto the next visual line.
                    io::print_line(&line);
                } else {
                    io::print_line(&line);
                }
                io::sleep(Duration::from_millis(utils::range(0, 100)));
            }
        }
        if io::should_exit() {
            return;
        }
    }
}
RS"}

