{"command":"python3 - << 'PY'
import glob,re,json
cats={'dirs':set(),'files':set(),'symbols':set(),'strings':set(),'scans':set(),'misc':set(),'headings':set(),'roots':set()}
for f in glob.glob('/tmp/orig_out/samples/rkhunter_*.out')+glob.glob('/tmp/orig_out/modules/rkhunter.out'):
 d=open(f,'rb').read().decode(errors='ignore')
 d=re.sub(r'\x1b\[[0-9;]*m','',d)
 for line in d.split('\r\n'):
  s=line.strip()
  if s.startswith('Performing '): cats['headings'].add(s)
  m=re.match(r"Checking for (.+ Rootkit|LKM)\.\.\.$",s)
  if m: cats['roots'].add(m.group(1))
  m=re.match(r"(?:Checking|Scanning) for (?:directory|file|string) '([^']+)'",s)
  # handle lower below separately
  if "Checking for directory '" in s: cats['dirs'].add(re.search(r"directory '([^']+)'",s).group(1))
  elif "Checking for file '" in s: cats['files'].add(re.search(r"file '([^']+)'",s).group(1))
  elif "Checking for kernel symbol '" in s: cats['symbols'].add(re.search(r"symbol '([^']+)'",s).group(1))
  elif "Checking for string '" in s: cats['strings'].add(re.search(r"string '([^']+)'",s).group(1))
  elif s.startswith('Scanning for string '): cats['scans'].add(re.sub(r'\s+\[.*$','',s[len('Scanning for string '):]))
  elif (s.startswith('Checking ') or s.startswith('Running ')) and '[' in s:
      desc=re.sub(r'\s+\[.*$','',s)
      cats['misc'].add(desc)
print({k:len(v) for k,v in cats.items()})
for k,v in cats.items(): print(k,sorted(v)[:30])
json.dump({k:sorted(v) for k,v in cats.items()},open('/tmp/rk.json','w'))
PY"}

