static SYMBOLS: &[&str] = &[
    "find_sys_call_tbl", "h4x_read", "h4x_rename", "h4x_tcp4_seq_show", "h4x_write", "hide_module",
    "kernel_unlink", "rootme", "sys_call_hijack", "hide_port", "hacked_getdents",
];

static STRINGS: &[&str] = &[
    "#<HIDE_.*>", "/bin/envpc", "/dev/ida/.inet", "/dev/ptyxx/.file", "/dev/ptyxx/.proc",
    "/lib/ldd.so/tkps", "/lib/libext", "/tmp/.sendmail", "/usr/bin/hdparm?-t1?-X53?-p",
    "/usr/include/openssl", "/usr/lib/.tbd", "/usr/sbin/login", "$.*$!.*!!$", "IptabLes",
    "IptabLex", "L4m3r0x", "backdoor_active", "in.inetd", "joao", "libproc.so.2.0.7", "phalanx",
    "sendmail", "vt200",
];

static SCANS: &[&str] = &[
    "/dev/.lib/lib/scan", "/usr/include/.../.bash_history", "/usr/include/.../bkit-dl",
    "/usr/include/.../bkit-screen", "/usr/lib/.../bkit-ssh/bkit-pw", "/usr/lib/.../du",
    "/usr/lib/.../lsof", "/usr/lib/.../netstat", "/usr/lib/.../psr", "/usr/lib/.../pstree",
    "/usr/lib/.../top", "/usr/sbin/.../bkit-f", "/usr/sbin/.../bkit-shd",
];

static MISC: &[&str] = &[
    "Checking LD_LIBRARY_PATH variable",
    "Checking for a system logging configuration file",
    "Checking for hidden files and directories",
    "Checking for local host name",
    "Checking for missing log files",
    "Checking for other suspicious configuration settings",
    "Checking for passwd file",
    "Checking for root equivalent (UID 0) accounts",
    "Checking for suspicious directories",
    "Checking for system startup files",
    "Checking if SSH protocol v1 is allowed",
    "Checking root account shell history files",
    "Checking system startup files for malware",
    "Running skdet command",
];

static PORTS: &[u64] = &[
    22, 80, 443, 1984, 2128, 6666, 6667, 7000, 13000, 27960, 31337, 32982, 33369, 60001, 62883, 65535,
];

fn status() -> &'static str {
    let roll = utils::range(0, 100);
    if roll < 86 {
        "Not found"
    } else if roll < 96 {
        "Found"
    } else {
        "Skipped"
    }
}

fn coloured(status: &str) -> String {
    if status == "Found" {
        format!("\x1b[31m{status}\x1b[0m")
    } else {
        format!("{status}\x1b[0m")
    }
}

fn build_checks() -> Vec<String> {
    let mut checks = Vec::new();

    for port in utils::choose_multiple(PORTS, utils::range(0, 4) as usize) {
        checks.push(format!("Checking for TCP port {port}"));
    }
    let mut directories: Vec<String> = utils::choose_multiple(DIRECTORIES, utils::range(0, 7) as usize)
        .into_iter()
        .map(|path| path.to_string())
        .collect();
    directories.sort();
    checks.extend(directories.iter().map(|path| format!("Checking for directory '{path}'")));

    let mut files: Vec<String> = utils::choose_multiple(FILES, utils::range(3, 12) as usize)
        .into_iter()
        .map(|path| path.to_string())
        .collect();
    files.sort();
    checks.extend(files.iter().map(|path| format!("Checking for file '{path}'")));

    let mut symbols: Vec<String> = utils::choose_multiple(SYMBOLS, utils::range(0, 4) as usize)
        .into_iter()
        .map(|symbol| symbol.to_string())
        .collect();
    symbols.sort();
    checks.extend(symbols.iter().map(|symbol| format!("Checking for kernel symbol '{symbol}'")));

    checks.extend(
        utils::choose_multiple(MISC, utils::range(0, 5) as usize)
            .into_iter()
            .map(|text| text.to_string()),
    );

    let mut strings: Vec<String> = utils::choose_multiple(STRINGS, utils::range(0, 6) as usize)
        .into_iter()
        .map(|text| text.to_string())
        .collect();
    strings.sort();
    checks.extend(strings.iter().map(|text| format!("Checking for string '{text}'")));

    let mut scans: Vec<String> = utils::choose_multiple(SCANS, utils::range(0, 5) as usize)
        .into_iter()
        .map(|path| path.to_string())
        .collect();
    scans.sort();
    checks.extend(scans.iter().map(|path| format!("Scanning for string {path}")));
    checks
}

fn print_checks(indent: &str, checks: &[String]) -> bool {
    let width = checks
        .iter()
        .map(|check| indent.len() + check.chars().count())
        .max()
        .unwrap_or(0);
    let mut any_found = false;
    for check in checks {
        if io::should_exit() {
            return any_found;
        }
        let status = status();
        any_found |= status == "Found";
        let description = format!("{indent}{check}");
        print!("{description:<width$} [ {} ]\r\n", coloured(status), width = width);
        let _ = std::io::stdout().flush();
        io::sleep(Duration::from_millis(utils::range(50, 400)));
    }
    any_found
}

pub fn run() {
    let start = chrono::Utc::now().format("%a %d %b %Y %I:%M:%S %p UTC");
    print!(
        "Running Rootkit Hunter version {} on localhost\r\n\r\n\
         Info: Start date is {start}\r\n\r\n\
         Info: Detected operating system is 'Linux'\r\n\
         Found O/S name: Ubuntu {}\
         Info: Environment shell is /bin/bash; rkhunter is using dash\r\n\
         Info: Using configuration file '/etc/rkhunter.conf'\r\n\
         Info: Installation directory is '/usr'\r\n\
         Info: Using language 'en'\r\n\
         Info: Using '/var/lib/rkhunter/db' as the database directory\r\n\
         Info: Using '/usr/share/rkhunter/scripts' as the support script directory\r\n\
         Info: Using '/var/lib/rkhunter/db' as the database directory\r\n\
         Info: Using '/usr/share/rkhunter/scripts' as the support script directory\r\n\
         Info: Using '/usr/local/sbin /usr/local/bin /usr/sbin /usr/bin /sbin /bin /usr/games /usr/local/games /snap/bin /usr/libexec' as the command directories\r\n\
         Info: Using '/var/lib/rkhunter/tmp' as the temporary directory\r\n\
         Info: No mail-on-warning address configured\r\n\r\n\
         Checking if the O/S has changed since last time...\r\n\
         Info: Nothing seems to have changed.\r\n\
         Info: Locking is not being used\r\n\r\n\
         Starting system checks...\r\n\r\n",
        utils::version(),
        utils::version()
    );

    let heading = utils::choose_str(HEADINGS);
    print!("{heading}\r\n");

    if utils::probability(0.5) {
        let rootkit = utils::choose_str(ROOTKITS);
        print!("  Checking for {rootkit}...\r\n");
        let mut checks = build_checks();
        if utils::probability(0.35) {
            checks.insert(0, "Checking LD_LIBRARY_PATH variable".to_string());
        }
        let found = print_checks("    ", &checks);
        if io::should_exit() {
            return;
        }
        let width = checks
            .iter()
            .map(|check| 4 + check.chars().count())
            .max()
            .unwrap_or(0);
        let status = if found { "Found" } else { "Not found" };
        let description = format!("  {rootkit}");
        print!("{description:<width$} [ {} ]\r\n", coloured(status), width = width);
    } else {
        let checks = build_checks();
        print_checks("  ", &checks);
        if io::should_exit() {
            return;
        }
    }
    print!("\r\n");
}
RS"}

