    "  \x1b[1;34m(_)\x1b[0m     | \x1b[1;31m(_)\x1b[0m \x1b[1;35m(_)\x1b[0m    |\r\n",
    "   _ _   _| |_  __ _   |  Type \"?\" for help, \"]?\" for Pkg help.\r\n",
    "  | | | | | | |/ _` |  |\r\n",
    "  | | |_| | | | (_| |  |  Version 1.7.3 (2022-05-06)\r\n",
    " _/ |\\__'_|_|_|\\__'_|  |  Fedora 35 build\r\n",
    "|__/                   |\r\n",
    "\r\n",
);

fn green_label(label: &str) -> String {
    format!("\x1b[1;32m{label:>12}\x1b[0m")
}

fn older_version(version: &str) -> String {
    let (base, suffix) = match version.split_once('+') {
        Some((base, suffix)) => (base, Some(suffix)),
        None => (version, None),
    };
    let mut parts: Vec<u64> = base
        .split('.')
        .map(|part| part.parse().unwrap_or(0))
        .collect();
    while parts.len() < 3 {
        parts.push(0);
    }
    // Reduce the last component that can be reduced, then put
    // something plausible in the components after it.
    for index in (0..parts.len()).rev() {
        if parts[index] > 0 {
            let amount = utils::range(1, parts[index] + 1).min(parts[index]);
            parts[index] -= amount;
            for later in &mut parts[index + 1..] {
                *later = utils::range(0, 20);
            }
            break;
        }
    }
    let mut old = parts
        .iter()
        .map(|part| part.to_string())
        .collect::<Vec<_>>()
        .join(".");
    if let Some(suffix) = suffix {
        old.push('+');
        old.push_str(suffix);
    }
    old
}

fn progress_line(label: &str, fraction: f64, suffix: String) {
    io::print_line(&format!(
        "\x1b[1;36m{label}\x1b[0m [{}] {suffix}",
        utils::equals_block_bar(fraction, 41)
    ));
}

pub fn run() {
    print!("{BANNER}");
    let _ = std::io::stdout().flush();

    let count = utils::range(10, 100) as usize;
    let packages: Vec<(&str, &str)> = utils::choose_multiple(JULIA_PACKAGES, count)
        .into_iter()
        .map(|(name, version)| (*name, *version))
        .collect();
    let artifact_count = utils::range(1, 10) as usize;
    let artifacts: Vec<&str> = utils::choose_multiple(JULIA_PACKAGES, artifact_count)
        .into_iter()
        .map(|(name, _)| *name)
        .collect();

    let default_environment = utils::probability(0.5);
    let project = if default_environment {
        "@v1.7".to_string()
    } else {
        utils::choose(JULIA_PACKAGES).0.to_string()
    };

    io::print_str("\x1b[1;32mjulia>\x1b[0m ");
    io::sleep(Duration::from_millis(utils::range(100, 500)));
    io::erase_line();
    io::print_str(&format!("\x1b[1;34m({project}) pkg>\x1b[0m "));
    io::print_with_delay("update", Duration::from_millis(80));
    io::print_line("");

    io::print_line(&format!(
        "{} registry at `~/.julia/registries/General.toml`",
        green_label("Updating")
    ));
    io::print_line(&format!(
        "{} package versions...",
        green_label("Resolving")
    ));
    io::sleep(Duration::from_millis(utils::range(100, 500)));

    for (name, version) in &packages {
        let dashes = 27usize.saturating_sub(name.len()).max(1);
        io::print_line(&format!(
            "{} {name} {} v{version}",
            green_label("Installed"),
            "─".repeat(dashes)
        ));
        io::sleep(Duration::from_millis(utils::range(20, 200)));
    }

    for artifact in &artifacts {
        io::print_line(&format!(
            "\x1b[1;32m Downloading\x1b[0m artifact: {artifact}"
        ));
        let mut fraction = 0.0f64;
        progress_line("    Downloading", fraction, "0.00%".to_string());
        loop {
            fraction += (1.0 - fraction) * (0.01 + utils::range(0, 120) as f64 / 1000.0);
            io::move_up_and_erase_line();
            progress_line(
                "    Downloading",
                fraction,
                format!("{:.2}%", (fraction * 100.0).min(100.0)),
            );
            io::sleep(Duration::from_millis(50));
            if fraction > 0.99995 {
                break;
            }
        }
        io::move_up_and_erase_line();
        io::move_up_and_erase_line();
        io::print_line(&format!(
            "\x1b[1;32m  Downloaded\x1b[0m artifact: {artifact}"
        ));
    }

    let warnings = default_environment && utils::probability(0.5);
    if warnings {
        io::print_line(
            "\x1b[1;33m┌ Warning:\x1b[0m The active manifest file at `~/.julia/environments/v1.7/Manifest.toml` has an old format that is being maintained.",
        );
        io::print_line(
            "\x1b[1;33m│\x1b[0m To update to the new format run `Pkg.upgrade_manifest()` which will upgrade the format without re-resolving.",
        );
        io::print_line(
            "\x1b[1;33m└\x1b[0m \x1b[38;5;8m@ Pkg.Types /builddir/build/BUILD/julia-1.7.3/build/usr/share/julia/stdlib/v1.7/Pkg/src/manifest.jl:287\x1b[0m",
        );
    }

    let project_dir = if default_environment {
        "~/.julia/environments/v1.7".to_string()
    } else {
        format!("~/Documents/code/julia/projects/{project}.jl")
    };
    io::print_line(&format!(
        "{} `{project_dir}/Project.toml`",
        green_label("Updating")
    ));
    io::print_line(&format!(
        "{} `{project_dir}/Manifest.toml`",
        green_label("Updating")
    ));

    if warnings {
        io::print_line(
            "\x1b[1;33m┌ Warning:\x1b[0m The active manifest file is an older format with no julia version entry. Dependencies may have been resolved with a different julia version.",
        );
        io::print_line(
            "\x1b[1;33m└\x1b[0m \x1b[38;5;8m@ ~/.julia/environments/v1.7/Manifest.toml:0\x1b[0m",
        );
    }

    for (name, version) in &packages {
        let change = if utils::probability(0.5) {
            format!(
                "\x1b[38;5;11m↑ {name} v{} ⇒ v{version}\x1b[0m",
                older_version(version)
            )
        } else {
            format!("\x1b[38;5;10m+ {name} v{version}\x1b[0m")
        };
        io::print_line(&format!(
            "  \x1b[38;5;8m[{}]\x1b[0m {change}",
            utils::hex_string(4)
        ));
        io::sleep(Duration::from_millis(utils::range(20, 150)));
    }

    progress_line("  Progress", 0.0, format!("0/{artifact_count}"));
    for (index, artifact) in artifacts.iter().enumerate() {
        io::move_up_and_erase_line();
        let dashes = 25usize.saturating_sub(artifact.len()).max(1);
        let uuid = format!(
            "{}-{}-{}-{}-{}",
            utils::hex_string(4),
            utils::hex_string(2),
            utils::hex_string(2),
            utils::hex_string(2),
            utils::hex_string(6)
        );
        io::print_line(&format!(
            "{} {artifact} {}→ `~/.julia/scratchspaces/{uuid}/{}/build.log`",
            green_label("Building"),
            "─".repeat(dashes),
            utils::hex_string(20)
        ));
        let done = index + 1;
        progress_line(
            "  Progress",
            done as f64 / artifact_count as f64,
            format!("{done}/{artifact_count}"),
        );
        io::sleep(Duration::from_millis(utils::range(50, 250)));
    }

    io::move_up_and_erase_line();
    io::print_line("\x1b[1;32mPrecompiling\x1b[0m project...");
    progress_line("  Progress", 0.0, format!("0/{count}"));
    for done in 1..=count {
        io::move_up_and_erase_line();
        progress_line(
            "  Progress",
            done as f64 / count as f64,
            format!("{done}/{count}"),
        );
        io::sleep(Duration::from_millis(30));
    }

    io::move_up_and_erase_line();
    io::print_line(&format!(
        "  {count} dependencies successfully precompiled in 0 seconds ({} already precompiled)",
        utils::range(0, 500)
    ));
    io::print_line("");
    io::print_str(&format!("\x1b[1;34m({project}) pkg>\x1b[0m "));
    io::sleep(Duration::from_millis(utils::range(100, 400)));
    io::erase_line();
    io::print_str("\x1b[1;32mjulia>\x1b[0m ");
    io::sleep(Duration::from_millis(utils::range(100, 400)));
    io::print_line("");
}
RS"}

