{"command":"cat > src/modules/uv.rs << 'RS'
use crate::data::CRATES;
use crate::io;
use crate::utils;
use std::time::{Duration, Instant};

struct Package {
    name: String,
    version: String,
    size: u64,
    rate: u64,
}

fn python_version() -> String {
    let minor = utils::range(8, 15);
    let patch = utils::range(0, 26);
    format!("3.{minor}.{patch}")
}

pub fn run() {
    let started = Instant::now();
    io::print_line(&format!("Using CPython {}", python_version()));
    io::print_line("Creating virtualenv at: .venv");

    let resolved_count = utils::range(100, 300) as usize;
    let installed_count = utils::range(50, 220).min(resolved_count as u64) as usize;
    let resolved: Vec<Package> = utils::choose_multiple(CRATES, resolved_count)
        .into_iter()
        .map(|name| Package {
            name: name.to_string(),
            version: utils::version(),
            size: utils::range(100_000, 20_000_000),
            rate: utils::range(100_000, 2_000_000),
        })
        .collect();

    let spinner = utils::BRAILLE_SPINNER;
    let resolve_started = Instant::now();
    for (index, package) in resolved.iter().enumerate() {
        if io::should_exit() {
            return;
        }
        io::erase_line();
        io::print_str(&format!(
            "{} {}=={}",
            spinner[index % spinner.len()],
            package.name,
            package.version
        ));
        io::sleep(Duration::from_millis(2));
    }
    io::erase_line();
    io::print_str(&format!(
        "\x1b[2mResolved {} packages in {:.2}ms\x1b[0m",
        resolved.len(),
        resolve_started.elapsed().as_secs_f64() * 1000.0
    ));

    let packages = &resolved[..installed_count];
    let prepare_started = Instant::now();
    for index in 0..packages.len() {
        if io::should_exit() {
            return;
        }
        io::erase_line();
        io::print_str(&format!(
            "\x1b[2m{} Preparing packages... ({}/{})\x1b[0m",
            spinner[index % spinner.len()],
            index + 1,
            packages.len()
        ));
        io::sleep(Duration::from_millis(2));
    }
    io::erase_line();
    io::print_str(&format!(
        "\x1b[2mPrepared {} packages in {:.2}ms\x1b[0m",
        packages.len(),
        prepare_started.elapsed().as_secs_f64() * 1000.0
    ));
    io::print_str("\r\n\r\n");

    let name_width = packages
        .iter()
        .map(|package| package.name.chars().count())
        .max()
        .unwrap_or(0);
    for package in packages {
        let mut downloaded = 0u64;
        loop {
            if io::should_exit() {
                return;
            }
            downloaded = (downloaded + package.rate).min(package.size);
            let fraction = downloaded as f64 / package.size as f64;
            let filled = (fraction * 30.0) as usize;
            let bar = format!("{}{}", "-".repeat(filled), " ".repeat(30 - filled));
            let current = utils::human_binary(downloaded, true);
            let total = utils::human_binary(package.size, true);
            let sizes = format!("{current}/{total}");
            io::move_up_and_erase_line();
            io::print_line(&format!(
                "\x1b[2m{:<name_width$}\x1b[0m \x1b[32m{bar}\x1b[0m {sizes:^21}",
                package.name,
                name_width = name_width
            ));
            io::sleep(Duration::from_millis(20));
            if downloaded >= package.size {
                break;
            }
        }
    }

    io::move_up_and_erase_line();
    for done in 0..=packages.len() {
        if io::should_exit() {
            return;
        }
        let filled = if done == 0 {
            0
        } else {
            ((done * 30) as f64 / packages.len() as f64).ceil() as usize
        };
        let bar = format!("{}{}", "█".repeat(filled), "░".repeat(30 - filled));
        io::erase_line();
        io::print_str(&format!("[{bar}] [{done}/{}] Installing wheels...", packages.len()));
        io::sleep(Duration::from_millis(10));
    }

    io::erase_line();
    io::print_line(&format!(
        "\x1b[2mInstalled {} packages in {:.2}s\x1b[0m",
        packages.len(),
        started.elapsed().as_secs_f64()
    ));
}
RS"}

