            "\x1b[A\x1b[K[{completed}/{total}] No tests running."
        ));
        return;
    }
    let mut line = format!("\x1b[A\x1b[K[{completed}/{total}] ");
    for _ in 0..running {
        line.push_str(&test_path());
        line.push(' ');
    }
    io::print_line(&line);
}

fn assertion() -> String {
    if utils::probability(0.5) {
        return "assert_".to_string();
    }
    match utils::range(0, 5) {
        0 => "assert_true: expected true but got false".to_string(),
        1 => format!(
            "assert_equals: expected {} but got {}",
            utils::range(0, 1000),
            utils::range(0, 1000)
        ),
        2 => format!(
            "assert_approx_equals: expected {} +/- {} but got {}",
            utils::range(0, 100),
            utils::range(1, 10),
            utils::range(0, 100)
        ),
        3 => format!(
            "assert_array_equals: expected property {} to be {} but got {}",
            utils::range(0, 20),
            utils::range(0, 20),
            utils::range(0, 20)
        ),
        _ => "assert_throws_dom: function \"() => test()\" threw object \"TypeError: undefined is not a function\" that is not a DOMException".to_string(),
    }
}

fn stack_location(path: &str) -> String {
    let harness_line = utils::choose(&[633, 1467, 1518, 2869]);
    match utils::range(0, 100) {
        0..=22 => "<unknown>".to_string(),
        23..=42 => format!(
            "assert_wrapper (http://web-platform.test:8000/resources/testharness.js:{harness_line}:35)"
        ),
        43..=59 => format!(
            "test (http://web-platform.test:8000/resources/testharness.js:{harness_line}:34)"
        ),
        60..=72 => format!(
            "http://web-platform.test:8000/resources/testharness.js:{harness_line}:{}",
            utils::range(20, 50)
        ),
        _ => format!(
            "http://web-platform.test:8000/{path}:{}:{}",
            utils::range(1, 150),
            utils::range(1, 100)
        ),
    }
}

fn print_event(path: &str) {
    let timed_out = utils::probability(0.5);
    let expected = if utils::probability(0.5) { "PASS" } else { "FAIL" };
    let (header, actual) = if timed_out {
        (format!("    ▶ Timed out in {path}"), "TIMEOUT")
    } else {
        let actual = if expected == "PASS" { "FAIL" } else { "PASS" };
        (
            format!("    ▶ Unexpected subtest result in {path}:"),
            actual,
        )
    };
    io::print_line(&format!("\x1b[A\x1b[K{header}"));
    io::print_line(&format!(
        "    │ ERROR [expected {expected}] {actual} test_{} {}",
        test_suffix(path),
        assertion()
    ));

    if !timed_out {
        let frames = utils::range(1, 9);
        for frame in 0..frames {
            let branch = if frame + 1 == frames { "└" } else { "│" };
            io::print_line(&format!("    {branch}   at {}", stack_location(path)));
        }
        io::print_line("");
    }
}

pub fn run() {
    let total = utils::range(10_000, 30_000);
    let subtests = total * utils::range(25, 40) + utils::range(0, total);
    io::print_line(&format!("Running {total} tests in web-platform-tests"));
    io::print_line(&format!("\x1b[A\x1b[K[0/{total}] No tests running."));

    // The first handful of results arrive before the runner has a
    // current test to name in its reports.
    let mut completed = 0u64;
    let mut failed = 0u64;
    for _ in 0..15 {
        print_event("");
        failed += 1;
        completed += 1;
    }

    while completed < total {
        status_line(completed, total);
        io::sleep(Duration::from_millis(250));
        let batch = utils::range(1, 11);
        for _ in 0..batch {
            // Almost, but not quite, every test yields a failure
            // report in this rather unfortunate test run.
            if utils::probability(0.94) {
                print_event(&test_path());
                failed += 1;
            }
            completed += 1;
        }
    }

    io::print_line(&format!(
        "\x1b[A\x1b[KRan {completed}/{total} tests with {failed} failed subtests of {subtests}."
    ));
}
