cat > src/modules/docker_build.rs << 'RS'
use crate::args::Module;
use crate::data::DOCKER_IMAGES;
use crate::io;
use crate::utils;
use std::time::Duration;

static COMMANDS: &[(Module, &str)] = &[
    (Module::Ansible, "RUN ansible-playbook"),
    (
        Module::Bootlog,
        "RUN bcdedit /set {current} bootlog Yes && shutdown /r",
    ),
    (Module::Botnet, "RUN ./botnet.sh"),
    (Module::Bruteforce, "RUN ./bruteforce.sh ./hashes.txt"),
    (Module::Cargo, "RUN cargo run"),
    (Module::Cc, "RUN gcc app.c"),
    (Module::Composer, "RUN composer install"),
    (
        Module::Cryptomining,
        "RUN ./cryptominer.sh --gpu all --provider stratum",
    ),
    (Module::Download, "RUN wget -i downloads.txt"),
    (Module::Julia, "RUN julia --threads auto --project ."),
    (Module::KernelCompile, "RUN sudo make install"),
    (Module::Memdump, "RUN memdump -k -v"),
    (
        Module::Mkinitcpio,
        "RUN mkinitcpio --generate /boot/initramfs-custom2.img --kernel 5.7.12-arch1-1",
    ),
    (Module::Rkhunter, "RUN rkhunter --check"),
    (Module::Simcity, "RUN ./start-sumcity.sh"),
    (Module::Terraform, "RUN terraform --check"),
    (Module::Uv, "RUN uv sync"),
    (Module::Weblog, "RUN tail -f /var/log/nginx/access.log"),
    (
        Module::Wpt,
        "RUN wpt run -f --browser-version=\"1.0\" --processes=16",
    ),
];

pub fn run() {
    // First the build context is uploaded a chunk at a time.
    let mut sent = 0.0f64;
    loop {
        if io::should_exit() {
            return;
        }
        io::print_str(&format!(
            "\rSending build context to Docker daemon  {sent:.2}MB"
        ));
        io::sleep(Duration::from_millis(50));
        sent += 5.0 + utils::range(0, 2500) as f64 / 100.0;
        if sent > 200.0 && utils::probability(0.08) {
            break;
        }
        if sent > 900.0 {
            break;
        }
    }

    let steps = utils::range(30, 100);
    for step in 1..=steps {
        let (module, command) = utils::choose(COMMANDS);
        io::print_str("\r");
        io::print_line(&format!("Step {step}/{steps} : {command}"));
        if io::should_exit() {
            return;
        }
        if utils::probability(0.68) {
            io::print_line(&format!(" ---> Using cache ---> {}", utils::hex_string(6)));
            io::sleep(Duration::from_millis(50));
        } else {
            io::print_line(&format!(" ---> Running in {}", utils::hex_string(6)));
            crate::modules::run(*module);
            if io::should_exit() {
                return;
            }
        }
    }

    let image = utils::choose_str(DOCKER_IMAGES);
    // A Docker image pair from the data already carries its tag, but
    // `Successfully tagged` normally prints the same name again.
    io::print_str(&format!("Successfully built {}", utils::hex_string(6)));
    io::print_str(&format!("Successfully tagged {image}"));
}
RS"}

