static AREAS: &[&str] = &[
    "WebAssembly", "WebGL", "accelerometer", "accessibility", "battery", "beacon", "cookies",
    "dom/abort", "dom/elements", "dom/events", "editing/defs", "encoding", "encrypted-media",
