import re,collections
ls=open('/tmp/orig_out/modules/wpt.out','rb').read().decode(errors='ignore').split('\r\n')
paths=[]
for l in ls:
 m=re.search(r'(?:Timed out in|Unexpected subtest result in) ([^:]+):?$',l) or re.search(r'(?:Timed out in) (.+)$',l)
 if m: paths.append(m.group(1))
# Use simpler extract after in
paths=[]
for l in ls:
 if 'Timed out in ' in l: paths.append(l.split('Timed out in ',1)[1])
 elif 'Unexpected subtest result in ' in l: paths.append(l.split('Unexpected subtest result in ',1)[1].rstrip(':'))
runs=[]
