    let total = utils::range(10_000, 30_000);
    let subtests = total * utils::range(25, 40) + utils::range(0, total);
    io::print_line(&format!("Running {total} tests in web-platform-tests"));
    io::print_line(&format!("\x1b[A\x1b[K[0/{total}] No tests running."));

    let mut completed = 0u64;
    let mut failed = 0u64;

    // The first results arrive before the runner has named a current
    // test in one of its status lines.
    for _ in 0..15 {
        print_event("");
        failed += 1;
        completed += 1;
    }

    while completed < total {
        // One or two status updates, each with a fresh list of the
        // tests currently occupying the workers.
        let mut running: Vec<String> = Vec::new();
        for _ in 0..utils::range(1, 3) {
            completed += utils::range(0, 7);
            running = (0..utils::range(0, 17)).map(|_| test_path()).collect();
            if running.is_empty() {
                io::print_line(&format!("\x1b[A\x1b[K[{completed}/{total}] "));
                io::print_line(&format!(
                    "\x1b[A\x1b[K[{completed}/{total}] No tests running."
                ));
            } else {
                let mut line = format!("\x1b[A\x1b[K[{completed}/{total}] ");
                for path in &running {
                    line.push_str(path);
                    line.push(' ');
                }
                io::print_line(&line);
            }
            io::sleep(Duration::from_millis(250));
        }

        // The last test in the status list then disgorges a burst of
        // failed subtests.
        let current = running.last().cloned().unwrap_or_default();
        let burst = utils::range(1, 26);
        for _ in 0..burst {
            print_event(&current);
            failed += 1;
            completed += 1;
        }
    }

    io::print_line(&format!(
        "\x1b[A\x1b[KRan {completed}/{total} tests with {failed} failed subtests of {subtests}."
    ));
}
'''
