//! Best-effort idle inhibition.
//!
//! `--inhibit` asks the desktop session, through its D-Bus
//! screen saver service, not to blank the screen while a module is
//! "running".  A fresh request is made for every module so that the
//! stated reason can name the command being simulated.  In the
//! headless environments genact is often run in there is no session
//! bus at all, so failure is reported as a warning and execution
//! carries on without inhibition.

use crate::args::Module;
use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::os::unix::net::UnixStream;
use std::time::Duration;

const APP_NAME: &str = "io.github.svenstaro.genact";
const SCREENSAVER: &str = "org.freedesktop.ScreenSaver";

enum Connection {
    Unix(UnixStream),
    Tcp(TcpStream),
}

/// A live inhibition request.  Dropping the guard sends the matching
/// `UnInhibit` call for the cookie issued by the service.
pub struct Guard {
    connection: Option<Connection>,
    unique_name: Option<String>,
    cookie: Option<u32>,
    next_serial: u32,
}

impl Drop for Guard {
    fn drop(&mut self) {
        if let (Some(connection), Some(cookie)) = (self.connection.as_mut(), self.cookie) {
            let message = Message::method_call(
                self.next_serial,
                self.unique_name.as_deref(),
                SCREENSAVER,
                "/org/freedesktop/ScreenSaver",
                SCREENSAVER,
                "UnInhibit",
                Some("u"),
                &encode_u32(cookie),
            );
            let _ = connection.write_all(&message);
            // The reply is not interesting, but wait very briefly for
            // it so the request is not lost in the rush to close.
            let _ = connection.set_read_timeout(Some(Duration::from_millis(100)));
            let _ = Message::read_from(connection);
        }
    }
}

fn address_error(message: &str) -> String {
    format!("system: address error: {message}")
}

fn invalid_address() -> String {
    address_error(
        "Invalid address. See https://dbus.freedesktop.org/doc/dbus-specification.html#addresses",
    )
}

fn io_error(error: io::Error) -> String {
    format!("system: I/O error: {error}")
}

fn session_bus_address() -> String {
    if let Ok(address) = std::env::var("DBUS_SESSION_BUS_ADDRESS") {
        return address;
    }
    if let Ok(runtime_dir) = std::env::var("XDG_RUNTIME_DIR") {
        if !runtime_dir.is_empty() {
            return format!("unix:path={runtime_dir}/bus");
        }
    }
    let uid = unsafe { libc::getuid() };
    format!("unix:path=/run/user/{uid}/bus")
}

fn parse_address(address: &str) -> Result<Connection, String> {
    // A D-Bus address may contain several `;`-separated addresses.
    let first = address.split(';').next().unwrap_or_default();
    let (transport, rest) = first.split_once(':').ok_or_else(invalid_address)?;
    if rest.is_empty() {
        return Err(invalid_address());
    }

    match transport {
        "unix" => {
            let mut path: Option<String> = None;
            let mut abstract_name: Option<String> = None;
            for pair in rest.split(',') {
                let (key, value) = pair
                    .split_once('=')
                    .ok_or_else(|| address_error("unix: address is invalid"))?;
                match key {
                    "path" => path = Some(percent_decode(value)),
                    "abstract" => abstract_name = Some(percent_decode(value)),
                    "dir" | "tmpdir" => {}
                    _ => return Err(address_error("unix: address is invalid")),
                }
            }
            if let Some(path) = path {
                if path.is_empty() {
                    return Err(invalid_address());
                }
                return UnixStream::connect(path)
                    .map(Connection::Unix)
                    .map_err(io_error);
            }
            if let Some(name) = abstract_name {
                return connect_abstract(&name);
            }
            Err(address_error("unix: address is invalid"))
        }
        "tcp" => {
            let mut host = "localhost";
            let mut port: Option<&str> = None;
            for pair in rest.split(',') {
                if let Some((key, value)) = pair.split_once('=') {
                    match key {
                        "host" => host = value,
                        "port" => port = Some(value),
                        _ => {}
                    }
                }
            }
            let port = port.ok_or_else(invalid_address)?;
            TcpStream::connect(format!("{host}:{port}"))
                .map(Connection::Tcp)
                .map_err(io_error)
        }
        _ => Err(invalid_address()),
    }
}

fn percent_decode(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' && index + 2 < bytes.len() {
            if let Ok(byte) = u8::from_str_radix(&value[index + 1..index + 3], 16) {
                decoded.push(byte);
                index += 3;
                continue;
            }
        }
        decoded.push(bytes[index]);
        index += 1;
    }
    String::from_utf8_lossy(&decoded).into_owned()
}

fn connect_abstract(name: &str) -> Result<Connection, String> {
    use std::os::unix::ffi::OsStrExt;

    // Linux abstract sockets are addressed by a leading NUL byte.
    let mut address = Vec::with_capacity(name.len() + 1);
    address.push(0);
    address.extend_from_slice(name.as_bytes());
    let address = std::ffi::OsStr::from_bytes(&address);
    UnixStream::connect(address)
        .map(Connection::Unix)
        .map_err(io_error)
}

impl Connection {
    fn write_all(&mut self, bytes: &[u8]) -> Result<(), String> {
        match self {
            Connection::Unix(stream) => stream.write_all(bytes).map_err(io_error),
            Connection::Tcp(stream) => stream.write_all(bytes).map_err(io_error),
        }
    }

    fn read_exact(&mut self, bytes: &mut [u8]) -> Result<(), String> {
        match self {
            Connection::Unix(stream) => stream.read_exact(bytes).map_err(io_error),
            Connection::Tcp(stream) => stream.read_exact(bytes).map_err(io_error),
        }
    }

    fn set_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        match self {
            Connection::Unix(stream) => stream.set_read_timeout(timeout),
            Connection::Tcp(stream) => stream.set_read_timeout(timeout),
        }
    }

    fn read_line(&mut self) -> Result<String, String> {
        let mut line = Vec::new();
        let mut byte = [0u8; 1];
        loop {
            let read = match self {
                Connection::Unix(stream) => stream.read(&mut byte).map_err(io_error)?,
                Connection::Tcp(stream) => stream.read(&mut byte).map_err(io_error)?,
            };
            if read == 0 {
                break;
            }
            line.push(byte[0]);
            if byte[0] == b'\n' || line.len() > 4096 {
                break;
            }
        }
        Ok(String::from_utf8_lossy(&line).trim_end().to_string())
    }
}

// ---------------------------------------------------------------------
// Just enough of the D-Bus wire format for three method calls.

fn align_padding(offset: usize, alignment: usize) -> usize {
    (alignment - (offset % alignment)) % alignment
}

fn encode_u32(value: u32) -> Vec<u8> {
    value.to_le_bytes().to_vec()
}

fn encode_string(value: &str, offset_in_body: &mut usize, out: &mut Vec<u8>) {
    let padding = align_padding(*offset_in_body, 4);
    out.extend(std::iter::repeat_n(0, padding));
    *offset_in_body += padding;
    out.extend_from_slice(&(value.len() as u32).to_le_bytes());
    out.extend_from_slice(value.as_bytes());
    out.push(0);
    *offset_in_body += 4 + value.len() + 1;
}

fn encode_strings(values: &[&str]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut offset = 0;
    for value in values {
        encode_string(value, &mut offset, &mut out);
    }
    out
}

enum FieldValue<'a> {
    U32(u32),
    Str(&'a str),
    ObjectPath(&'a str),
    Signature(&'a str),
}

struct Message {
    message_type: u8,
    _serial: u32,
    reply_serial: Option<u32>,
    error_name: Option<String>,
    signature: Option<String>,
    body: Vec<u8>,
}

impl Message {
    fn method_call(
        serial: u32,
        sender: Option<&str>,
        destination: &str,
        path: &str,
        interface: &str,
        member: &str,
        signature: Option<&str>,
        body: &[u8],
    ) -> Vec<u8> {
        let mut fields: Vec<(u8, FieldValue)> = vec![
            (1, FieldValue::ObjectPath(path)),
            (2, FieldValue::Str(interface)),
            (3, FieldValue::Str(member)),
            (6, FieldValue::Str(destination)),
        ];
        if let Some(sender) = sender {
            fields.push((7, FieldValue::Str(sender)));
        }
        if let Some(signature) = signature {
            fields.push((8, FieldValue::Signature(signature)));
        }

        let mut header_fields = Vec::new();
        for (code, value) in fields {
            let offset = 16 + header_fields.len();
            header_fields.extend(std::iter::repeat_n(0, align_padding(offset, 8)));
            header_fields.push(code);
            match value {
                FieldValue::U32(number) => {
                    header_fields.extend([1, b'u', 0]);
                    let offset = 16 + header_fields.len();
                    header_fields.extend(std::iter::repeat_n(0, align_padding(offset, 4)));
                    header_fields.extend_from_slice(&number.to_le_bytes());
                }
                FieldValue::Str(text) => {
                    header_fields.extend([1, b's', 0]);
                    header_fields.extend_from_slice(&(text.len() as u32).to_le_bytes());
                    header_fields.extend_from_slice(text.as_bytes());
                    header_fields.push(0);
                }
                FieldValue::ObjectPath(text) => {
                    header_fields.extend([1, b'o', 0]);
                    header_fields.extend_from_slice(&(text.len() as u32).to_le_bytes());
                    header_fields.extend_from_slice(text.as_bytes());
                    header_fields.push(0);
                }
                FieldValue::Signature(text) => {
                    header_fields.extend([1, b'g', 0]);
                    header_fields.push(text.len() as u8);
                    header_fields.extend_from_slice(text.as_bytes());
                    header_fields.push(0);
                }
            }
        }

        let mut message = Vec::new();
        message.extend([b'l', 1, 0, 1]);
        message.extend_from_slice(&(body.len() as u32).to_le_bytes());
        message.extend_from_slice(&serial.to_le_bytes());
        message.extend_from_slice(&(header_fields.len() as u32).to_le_bytes());
        message.extend(header_fields);
        message.extend(std::iter::repeat_n(
            0,
            align_padding(message.len(), 8),
        ));
        message.extend(body);
        message
    }

    fn read_from(connection: &mut Connection) -> Result<Self, String> {
        let mut fixed = [0u8; 16];
        connection.read_exact(&mut fixed)?;
        let little_endian = fixed[0] == b'l';
        let read_u32 = |bytes: &[u8]| -> u32 {
            let bytes: [u8; 4] = bytes.try_into().unwrap_or_default();
            if little_endian {
                u32::from_le_bytes(bytes)
            } else {
                u32::from_be_bytes(bytes)
            }
        };
        let message_type = fixed[1];
        let body_length = read_u32(&fixed[4..8]) as usize;
        let serial = read_u32(&fixed[8..12]);
        let header_length = read_u32(&fixed[12..16]) as usize;
        let mut header = vec![0u8; header_length];
        connection.read_exact(&mut header)?;
        let padding = align_padding(16 + header_length, 8);
        let mut padding_bytes = vec![0u8; padding];
        connection.read_exact(&mut padding_bytes)?;
        let mut body = vec![0u8; body_length];
        connection.read_exact(&mut body)?;

        let mut parser = FieldParser {
            data: &header,
            position: 0,
            little_endian,
        };
        let mut reply_serial = None;
        let mut error_name = None;
        let mut signature = None;
        while parser.position < header.len() {
            parser.align(8);
            if parser.position >= header.len() {
                break;
            }
            let code = header[parser.position];
            parser.position += 1;
            let value_signature = parser.read_signature()?;
            let value = parser.read_value(&value_signature)?;
            match (code, value) {
                (4, ParsedValue::Text(text)) => error_name = Some(text),
                (5, ParsedValue::Number(number)) => reply_serial = Some(number),
                (8, ParsedValue::Text(text)) => signature = Some(text),
                _ => {}
            }
        }

        Ok(Self {
            message_type,
            _serial: serial,
            reply_serial,
            error_name,
            signature,
            body,
        })
    }

    fn body_u32(&self) -> Option<u32> {
        self.body
            .get(..4)?
            .try_into()
            .ok()
            .map(u32::from_le_bytes)
    }

    fn body_string(&self) -> Option<String> {
        if self.body.len() < 4 {
            return None;
        }
        let length = u32::from_le_bytes(self.body[..4].try_into().ok()?) as usize;
        let bytes = self.body.get(4..4 + length)?;
        Some(String::from_utf8_lossy(bytes).into_owned())
    }
}

enum ParsedValue {
    Number(u32),
    Text(String),
    Other,
}

struct FieldParser<'a> {
    data: &'a [u8],
    position: usize,
    little_endian: bool,
}

impl FieldParser<'_> {
    fn align(&mut self, alignment: usize) {
        self.position += align_padding(16 + self.position, alignment);
    }

    fn read_u32(&mut self) -> Result<u32, String> {
        self.align(4);
        let bytes = self
            .data
            .get(self.position..self.position + 4)
            .ok_or_else(|| io_error(io::Error::new(io::ErrorKind::UnexpectedEof, "short D-Bus message")))?;
        self.position += 4;
        Ok(if self.little_endian {
            u32::from_le_bytes(bytes.try_into().unwrap())
        } else {
            u32::from_be_bytes(bytes.try_into().unwrap())
        })
    }

    fn read_signature(&mut self) -> Result<String, String> {
        let length = *self
            .data
            .get(self.position)
            .ok_or_else(|| io_error(io::Error::new(io::ErrorKind::UnexpectedEof, "short D-Bus message")))?
            as usize;
        self.position += 1;
        let bytes = self
            .data
            .get(self.position..self.position + length)
            .ok_or_else(|| io_error(io::Error::new(io::ErrorKind::UnexpectedEof, "short D-Bus message")))?;
        self.position += length + 1;
        Ok(String::from_utf8_lossy(bytes).into_owned())
    }

    fn read_text(&mut self) -> Result<String, String> {
        let length = self.read_u32()? as usize;
        let bytes = self
            .data
            .get(self.position..self.position + length)
            .ok_or_else(|| io_error(io::Error::new(io::ErrorKind::UnexpectedEof, "short D-Bus message")))?;
        self.position += length + 1;
        Ok(String::from_utf8_lossy(bytes).into_owned())
    }

    fn skip(&mut self, alignment: usize, size: usize) {
        self.align(alignment);
        self.position += size;
    }

    fn read_value(&mut self, signature: &str) -> Result<ParsedValue, String> {
        let mut chars = signature.chars().peekable();
        self.read_one(&mut chars)
    }

    fn read_one(
        &mut self,
        signature: &mut std::iter::Peekable<std::str::Chars>,
    ) -> Result<ParsedValue, String> {
        let Some(kind) = signature.next() else {
            return Ok(ParsedValue::Other);
        };
        Ok(match kind {
            'y' => {
                self.skip(1, 1);
                ParsedValue::Other
            }
            'b' | 'i' | 'u' | 'h' => ParsedValue::Number(self.read_u32()?),
            'n' | 'q' => {
                self.skip(2, 2);
                ParsedValue::Other
            }
            'x' | 't' | 'd' => {
                self.skip(8, 8);
                ParsedValue::Other
            }
            's' | 'o' => ParsedValue::Text(self.read_text()?),
            'g' => ParsedValue::Text(self.read_signature()?),
            'v' => {
                let inner = self.read_signature()?;
                let mut inner_chars = inner.chars().peekable();
                self.read_one(&mut inner_chars)?
            }
            'a' => {
                let length = self.read_u32()? as usize;
                // Arrays begin with padding up to the element type.
                // Peeking at the element signature is enough to find
                // that alignment for the types a bus sends us, after
                // which the remaining bytes can simply be skipped.
                let element_alignment = match signature.peek() {
                    Some('x' | 't' | 'd' | '(' | '{') => 8,
                    Some('n' | 'q') => 2,
                    Some('b' | 'i' | 'u' | 'h' | 's' | 'o') => 4,
                    _ => 1,
                };
                self.align(element_alignment);
                self.position += length;
                // Consume the element signature without parsing its
                // values individually.
                let _ = self.consume_signature(signature);
                ParsedValue::Other
            }
            '(' | '{' => {
                self.align(8);
                let closing = if kind == '(' { ')' } else { '}' };
                while let Some(&next) = signature.peek() {
                    if next == closing {
                        signature.next();
                        break;
                    }
                    self.read_one(signature)?;
                }
                ParsedValue::Other
            }
            _ => ParsedValue::Other,
        })
    }

    fn consume_signature(&self, signature: &mut std::iter::Peekable<std::str::Chars>) {
        match signature.next() {
            Some('a') => self.consume_signature(signature),
            Some('(') => {
                while let Some(kind) = signature.peek() {
                    if *kind == ')' {
                        signature.next();
                        break;
                    }
                    self.consume_signature(signature);
                }
            }
            Some('{') => {
                self.consume_signature(signature);
                self.consume_signature(signature);
                signature.next();
            }
            _ => {}
        }
    }
}

fn authenticate(connection: &mut Connection) -> Result<(), String> {
    let uid = unsafe { libc::getuid() }.to_string();
    let mut hex_uid = String::new();
    for byte in uid.as_bytes() {
        hex_uid.push_str(&format!("{byte:02x}"));
    }
    connection.write_all(format!("\0AUTH EXTERNAL {hex_uid}\r\n").as_bytes())?;
    let response = connection.read_line()?;
    if response.starts_with("OK ") {
        connection.write_all(b"NEGOTIATE_UNIX_FD\r\n")?;
        let negotiated = connection.read_line()?;
        if negotiated.starts_with("BEGIN") {
            // A particularly terse peer went straight to the binary
            // protocol; nothing else is needed here.
        } else {
            // `AGREE_UNIX_FD` is the usual answer and `ERROR` simply
            // means file descriptor passing is unavailable.
            connection.write_all(b"BEGIN\r\n")?;
        }
        return Ok(());
    }
    if let Some(mechanisms) = response.strip_prefix("REJECTED ") {
        let mechanisms: Vec<&str> = mechanisms.split_whitespace().collect();
        return Err(format!(
            "system: D-Bus handshake failed: EXTERNAL rejected by the server. Accepted mechanisms: [{}]",
            mechanisms.join(", ")
        ));
    }
    if response.is_empty() {
        return Err(io_error(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "failed to fill whole buffer",
        )));
    }
    Err(format!(
        "system: D-Bus handshake failed: unexpected response from server: {response}"
    ))
}

fn call(
    connection: &mut Connection,
    serial: u32,
    sender: Option<&str>,
    destination: &str,
    path: &str,
    member: &str,
    signature: Option<&str>,
    body: &[u8],
) -> Result<Message, String> {
    let message = Message::method_call(
        serial,
        sender,
        destination,
        path,
        // The interface has the same name as the destination for
        // both services used here.
        destination,
        member,
        signature,
        body,
    );
    connection.write_all(&message)?;
    loop {
        let reply = Message::read_from(connection)?;
        if reply.reply_serial != Some(serial) {
            continue;
        }
        if reply.message_type == 3 {
            let name = reply
                .error_name
                .clone()
                .unwrap_or_else(|| "org.freedesktop.DBus.Error.Failed".to_string());
            return Err(match reply.body_string() {
                Some(text) if !text.is_empty() => format!("system: {name}: {text}"),
                _ => format!("system: {name}"),
            });
        }
        return Ok(reply);
    }
}

fn try_connect(module: Module) -> Result<Guard, String> {
    let address = session_bus_address();
    let mut connection = parse_address(&address)?;
    let _ = connection.set_read_timeout(Some(Duration::from_secs(5)));
    authenticate(&mut connection)?;

    let hello = call(
        &mut connection,
        1,
        None,
        "org.freedesktop.DBus",
        "/org/freedesktop/DBus",
        "Hello",
        None,
        &[],
    )?;
    let unique_name = hello.body_string();

    let reason = format!("Running `{}`", module.command());
    let body = encode_strings(&[APP_NAME, &reason]);
    let reply = call(
        &mut connection,
        2,
        unique_name.as_deref(),
        SCREENSAVER,
        "/org/freedesktop/ScreenSaver",
        "Inhibit",
        Some("ss"),
        &body,
    )?;

    Ok(Guard {
        connection: Some(connection),
        unique_name,
        cookie: reply.body_u32(),
        next_serial: 3,
    })
}

/// Try to inhibit idle actions for one module, warning (on standard
/// output) if the session bus cannot be reached.
pub fn try_inhibit(module: Module) -> Guard {
    match try_connect(module) {
        Ok(guard) => guard,
        Err(error) => {
            println!("WARN: failed to set up idle inhibition: {error}");
            Guard {
                connection: None,
                unique_name: None,
                cookie: None,
                next_serial: 3,
            }
        }
    }
}
