    if response.starts_with("ERROR") {
        format!("system: D-Bus handshake failed: Received error from server: {response}")
    } else {
        let command = response.split_whitespace().next().unwrap_or_default();
        format!("system: D-Bus handshake failed: Unknown command: {command}")
