        if guid.len() != 32 || !guid.chars().all(|char| char.is_ascii_hexdigit()) {
            return Err("system: Invalid GUID".to_string());
        }
        connection.write_all(b"NEGOTIATE_UNIX_FD\r\n")?;
        let negotiated = connection.read_line()?;
        if negotiated.starts_with("BEGIN") {
            return Ok(());
        }
        if negotiated.starts_with("AGREE_UNIX_FD") || negotiated.starts_with("ERROR") {
            connection.write_all(b"BEGIN\r\n")?;
            return Ok(());
        }
        if negotiated.is_empty() {
            return Err(io_error(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "failed to fill whole buffer",
            )));
        }
        return Err(handshake_error(&negotiated));
    }
    if response == "OK" {
        return Err("system: Invalid GUID".to_string());
    }
    if let Some(mechanisms) = response.strip_prefix("REJECTED ") {
        let mechanisms: Vec<&str> = mechanisms.split_whitespace().collect();
        return Err(format!(
            "system: D-Bus handshake failed: EXTERNAL rejected by the server. Accepted mechanisms: [{}]",
            mechanisms.join(", ")
        ));
    }
    if response.is_empty() {
        return Err(io_error(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "failed to fill whole buffer",
        )));
    }
    Err(handshake_error(&response))
}
