new=r'''fn connect_abstract(name: &str) -> Result<Connection, String> {
    use std::os::unix::io::FromRawFd;

    // `UnixStream::connect` will not take a path with a leading NUL
    // byte, so make the socket and connect it by hand.
    let fd = unsafe { libc::socket(libc::AF_UNIX, libc::SOCK_STREAM, 0) };
    if fd < 0 {
        return Err(io_error(io::Error::last_os_error()));
    }
    let mut address: libc::sockaddr_un = unsafe { std::mem::zeroed() };
    address.sun_family = libc::AF_UNIX as libc::sa_family_t;
    let name_bytes = name.as_bytes();
    let path = unsafe {
        std::slice::from_raw_parts_mut(
            address.sun_path.as_mut_ptr() as *mut u8,
            address.sun_path.len(),
        )
    };
    if name_bytes.len() + 1 > path.len() {
        unsafe { libc::close(fd) };
        return Err(io_error(io::Error::new(
            io::ErrorKind::InvalidInput,
            "path must be shorter than SUN_LEN",
        )));
    }
    path[1..1 + name_bytes.len()].copy_from_slice(name_bytes);
    let length = (std::mem::size_of::<libc::sa_family_t>() + 1 + name_bytes.len())
        as libc::socklen_t;
    let result = unsafe {
        libc::connect(
            fd,
            &address as *const libc::sockaddr_un as *const libc::sockaddr,
            length,
        )
    };
    if result != 0 {
        let error = io::Error::last_os_error();
        unsafe { libc::close(fd) };
        return Err(io_error(error));
    }
    Ok(Connection::Unix(unsafe {
        UnixStream::from_raw_fd(fd)
    }))
}
