new=r'''fn try_connect(module: Module) -> Result<Guard, String> {
    let addresses = session_bus_address();
    let mut connection = None;
    let mut last_error = invalid_address();
    for address in addresses.split(';') {
        match parse_address(address) {
            Ok((connected, noncefile)) => {
                let mut connected = connected;
                if let Some(noncefile) = noncefile {
                    // A nonce-tcp peer expects the contents of the
                    // nonce file before the authentication exchange.
                    let nonce = std::fs::read(&noncefile).map_err(io_error)?;
                    connected.write_all(&nonce)?;
                }
                connection = Some(connected);
                break;
            }
            Err(error) => last_error = error,
        }
    }
    let mut connection = connection.ok_or(last_error)?;
    let _ = connection.set_read_timeout(Some(Duration::from_secs(5)));
    authenticate(&mut connection)?;

    let hello = call(
        &mut connection,
        1,
        None,
        "org.freedesktop.DBus",
        "/org/freedesktop/DBus",
        "Hello",
        None,
        &[],
    )?;
    let unique_name = hello.body_string();

    let reason = format!("Running `{}`", module.command());
    let body = encode_strings(&[APP_NAME, &reason]);
    let reply = call(
        &mut connection,
        2,
        unique_name.as_deref(),
        SCREENSAVER,
        "/org/freedesktop/ScreenSaver",
        "Inhibit",
        Some("ss"),
        &body,
    )?;

    Ok(Guard {
        connection: Some(connection),
        unique_name,
        cookie: reply.body_u32(),
        next_serial: 3,
    })
}
